window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch07"]={"id":"ch07","title":"第四章 细胞骨架 · 第二节 微丝","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"微丝结构 · 装配 · 肌球蛋白 · 功能","modules":[{"i":0,"name":"第二节 微丝 · 二、 微丝(Microfilament, MF)","slides":[{"i":0,"sec":"二、 微丝(Microfilament,","title":"二、 微丝(Microfilament, MF)","notes":"又称肌动蛋白纤维(Actin filament, F-actin)\n横纹肌\nα-actin     心肌    The α-actin is expressed only\n血管平滑肌 in muscle cells, while β,γ-actin\nG-actin                 肠道平滑肌 are found together in almost\nall nonmuscle cells.\nβ-actin\nγ-actin          非肌细胞\n进化中极为保守，不同真核生物间同源性很高。\n(Actins from amebas and from animals are identical at 80% of the amino acid\npositions despite about a billion years of evolution.)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 二、 微丝(Microfilament, MF) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是微丝(microfilament, MF)，又称肌动蛋白纤维(actin filament, F-actin)。微丝直径约7nm，由球形肌动蛋白(G-actin)组装而成。按序列与分布，肌动蛋白分为α-actin、β-actin和γ-actin：α-actin只表达于肌肉细胞(横纹肌、心肌、血管平滑肌、肠道平滑肌)，而β、γ-actin几乎共存于所有非肌细胞。原文还强调肌动蛋白在进化上极为保守，如变形虫与动物的肌动蛋白约80%氨基酸位点相同。对应翟中和《细胞生物学》第十章微丝的组成与类型，是基础考点。","page":1,"level":"掌握","img":"assets/img/ch07/p001.jpg","anim":null,"fig":null,"points":["直径7nm                组成蛋白：球形肌动蛋白(G-actin)"],"check":{"q":"关于「微丝(Microfilament, MF)」，下列说法正确的是（　）","o":["A. 直径7nm 组成蛋白：球形肌动蛋白(G-actin)","B. 单体隔离蛋白(monomer-sequestering-protein):","C. 头部(head domain)","D. 心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖"],"a":"A","e":"本页要点：直径7nm 组成蛋白：球形肌动蛋白(G-actin)","oe":["正确——微丝直径约7nm，由球形肌动蛋白G-actin组装而成。","单体隔离蛋白是微丝结合蛋白之一，不是微丝本身的定义。","头部结构域是肌球蛋白的结构特征，属微丝结合蛋白范畴。","心脏与胃肠蠕动依赖平滑肌收缩，非微丝的结构特征。"]},"cards":null},{"i":1,"sec":"二、 微丝(Microfilament,","title":"Lacking of MreB or Mbl (actin","notes":"control   homolog)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 二、 微丝(Microfilament, MF) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页是一张对照图，图注为control(对照)，实验组为Lacking of MreB or Mbl(缺失MreB或Mbl)。MreB、Mbl是细菌中肌动蛋白(actin)的同源蛋白(actin homolog)。细菌没有典型的真核微丝，但含有MreB/Mbl这类actin同源物，参与维持细胞形状等过程。原文文字残缺，仅能说明细菌中存在与真核肌动蛋白同源的蛋白，缺失后会影响细胞形态。可作为第十章“微丝在进化上高度保守”这一观点的佐证。","page":2,"level":"掌握","img":"assets/img/ch07/p002.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_1","mod":"第二节 微丝 · 二、 微丝(Microfilament, MF)","modI":0,"q":"关于「微丝(Microfilament, MF)」，下列说法正确的是（　）","o":["A. 微丝是由G-actin单体形成的多聚体","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，","D. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;"],"a":"B","e":"本页要点：直径7nm                组成蛋白：球形肌动蛋白(G-actin)","kp":"ch07_s0_0","oe":["微丝确由G-actin聚合形成，但题干考的是直径与组成蛋白","微丝直径约7nm，由球形肌动蛋白G-actin组成，正确","该说法正确，但描述微丝动态性，非直径与组成蛋白","该说法正确，但描述微丝极性，非直径与组成蛋白要点"]}],"judge":[{"id":"ch07_ajudge_2","modI":0,"q":"直径7nm                组成蛋白：球形肌动蛋白(G-actin)","a":"对","e":"本页要点：直径7nm                组成蛋白：球形肌动蛋白(G-actin)","kp":"ch07_s0_0"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":1,"name":"第二节 微丝 · 2.1 微丝的装配","slides":[{"i":2,"sec":"2.1 微丝的装配","title":"2.1 微丝的装配","notes":"与细胞形态的维持及细胞运动有关; 细胞内许多微丝结合蛋白\n参与调节微丝的装配\n体外\n通常高盐浓度聚合，低盐条件解聚\nMF/F-actin                             G-actin\nG-actin临界浓度, ATP\n聚合态                                     解聚态\nCa2+, Mg2+,Na+, K+离子浓度\n体内 ●永久性微丝: eg. 肌肉中细肌丝; 肠上皮细胞微绒毛中\n●暂时性微丝, 只在需要时装配: eg. 胞质分裂环中","page":3,"level":"掌握","img":"assets/img/ch07/p003.jpg","anim":null,"fig":null,"points":["微丝是由G-actin单体形成的多聚体","多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"check":{"q":"关于「微丝的装配」，下列说法正确的是（　）","o":["A. 细胞信号转导","B. Rapid disassembly and reassembly of","C. 微丝是由G-actin单体形成的多聚体","D. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;"],"a":"C","e":"本页要点：微丝是由G-actin单体形成的多聚体","oe":["细胞信号转导是微丝的功能之一，并非微丝装配的描述。","该英文描述微丝的动态装配，但不是本页装配要点。","正确——微丝是由G-actin单体聚合形成的F-actin多聚体。","该说法描述的是微丝极性，属装配的另一要点，非本题答案。"]},"cards":null},{"i":3,"sec":"2.1 微丝的装配","title":"单体actin 43kDa, 其上有一个ATP结合位点。ATP在微丝装配中","notes":"G-actin and F-actin\n具重要作用。聚合时，G-actin先要结合ATP, ATP-G-actin再结合\n到F-actin的两端；之后ATP水解成ADP。\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异","page":4,"level":"掌握","img":"assets/img/ch07/p004.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":4,"sec":"2.1 微丝的装配","title":"• 微丝是由G-actin单体形成的多聚体","notes":"Structure of G-actin and its assemble\nG-actin可加到MF两端，但其正极装配速度比负极快。\n【结合课本/笔记】装     配◆MF是由G-actin单体形成的多聚体，肌动蛋白单体具有极性,装配时呈头尾相接, 故微丝具有极性，既正极与负极之别。◆体外实验表明，MF正极与负极都能生长，生长快的一端为正极，慢的一端为负极；去装配时，负极比正极快。由于G-actin在正极端装配，负极去装配，从而表现为踏车行为。◆体内装配时，MF呈现出动态不稳定性，主要取决于F-actin结合的ATP水解速度与游离的G-actin单体浓度之间的关系。◆ MF动态变化与细胞生理功能变化相适应。在体内, 有些微丝是永久性的结构, 有些微丝是暂时性的结构。","page":5,"level":"掌握","img":"assets/img/ch07/p005.jpg","anim":null,"fig":null,"points":["actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;"],"check":{"q":"关于「• 微丝是由G-actin单体形成的多聚体」，下列说法正确的是（　）","o":["A. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;","B. 真菌的一种代谢产物(metabolite of fungal)","C. 肠上皮细胞(intestinal epithelial cells)表面细胞膜向","D. 动物成纤维细胞中微丝可以形成粗大的微丝束，即"],"a":"A","e":"本页要点：actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;","oe":["正确——G-actin单体具极性，头尾相接使F-actin也具极性。","真菌代谢产物指细胞松弛素，属微丝药物，非装配内容。","肠上皮细胞微绒毛的微丝束属微丝功能，非本题装配。","成纤维细胞的粗大微丝束即应力纤维，属微丝束内容。"]},"cards":null},{"i":5,"sec":"2.1 微丝的装配","title":"Structural polarity of the actin filament","notes":"【结合课本/笔记】●核纤层(Nuclear Lamina )一、微丝(microfilament, MF)又称肌动蛋白纤维(actin filament), 是指真核细胞中由肌动蛋白(actin)组成、直径为7nm的骨架纤维。●成分●装配●微丝特异性药物●微丝结合蛋白●微丝功能●肌肉收缩(muscle contraction)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是微丝的结构极性(structural polarity of the actin filament)。微丝由G-actin单体以同一方向首尾相连，因此两端结构不相同，分为(+)端(又称倒钩端，barbed end)和(−)端(又称尖头端，pointed end)。这种极性决定了微丝装配的方向性，也是踏车(treadmilling)行为以及肌球蛋白(myosin)等马达蛋白定向移动的基础。对应翟中和第十章微丝的极性，属于必须掌握的基本概念。","page":6,"level":"掌握","img":"assets/img/ch07/p006.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":6,"sec":"2.1 微丝的装配","title":"The polymerization of MFs and MTs in vitro","notes":"1. Nucleation (lag phase)\ncreate a stable template that serve as a “seed”for further\nelongation.\n2. Elongation\n3. Steady state — the rate of subunit addition is balanced exactly\nby the rate of subunit loss.\n微丝/微管体外的\n装配(聚合) 的三个\n阶段\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页讲微丝和微管的体外装配(聚合)(polymerization in vitro)可分为三个阶段：1.成核期(nucleation，又称滞后期lag phase)，若干亚基先正确结合形成稳定“种子”模板；2.延长期(elongation)，亚基在模板上继续添加；3.稳定期(steady state)，亚基添加速率与脱落速率恰好相等。原文还给出“微丝/微管体外装配的三个阶段”这一中文提示。这是第十章理解细胞骨架动态性的核心模型，常考三阶段的名称与特征。","page":7,"level":"掌握","img":"assets/img/ch07/p007.jpg","anim":null,"fig":null,"points":["An initial group of several subunits to associate correctly, to"],"check":{"q":"关于「The polymerization of MF…」，下列说法正确的是（　）","o":["A. Myosin I 重链无α-螺旋序","B. 细胞信号转导","C. An initial group of several subunits to associate correctly, to","D. Rapid disassembly and reassembly of"],"a":"C","e":"本页要点：An initial group of several subunits to associate correctly, to","oe":["Myosin I重链无α-螺旋属肌球蛋白结构，与微丝聚合无关。","细胞信号转导是微丝的功能，与聚合过程无关。","正确——微丝聚合起始时若干单体需正确结合形成核心。","快速解聚与重组装属微丝的动态性，非聚合起始描述。"]},"cards":null},{"i":7,"sec":"0.60μM              ","title":"“treadmilling” 脚踏车模型","notes":"One of the dynamics of actin/tubulin assembly:\n0.60μM                             0.12μM\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是肌动蛋白/微管装配的一种动力学——踏车模型(treadmilling，脚踏车模型)。原文标出0.60μM和0.12μM两个浓度，应分别对应微丝(+)端与(−)端的临界浓度。核心机制：当游离单体浓度介于两端临界浓度之间时，(+)端净添加、(−)端净脱落，单体仿佛“踩脚踏车”一样从一端流向另一端，而微丝总长度基本不变。这是翟中和第十章微丝动态装配的重要考点，需与成核、延长期区分。","page":8,"level":"掌握","img":"assets/img/ch07/p008.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":8,"sec":"0.60μM              ","title":"G-actin polymerization in vitro","notes":"The slowest step in the formation of an actin filament is the first\nstep, nucleation, which requires that at least 2 or 3 actin\nmonomers come together in the proper orientation to begin\nformation of the polymer.\nCells contain a protein complex, called the Arp2/3 (actin-\nrelated proteins) complex, that can nucleate F-actins\nboth in vitro and in vivo. (analogous to the way that γ-tubulin\nfor MT nucleation)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 成         分●肌动蛋白(actin)是微丝的结构成分,外观呈哑铃状, 这种actin又叫G-actin，将G-actin形成的微丝又称为F-actin。\n\n【本页英文讲解】\n本页主题是G-actin的体外聚合(polymerization in vitro)。原文指出，微丝形成中最慢的一步是成核(nucleation)，需要至少2~3个肌动蛋白单体以正确取向聚到一起，才能启动聚合物的形成。细胞内存在一种蛋白复合体——Arp2/3复合体(actin-related proteins complex)，能在体外和体内促进F-actin的成核，其作用类似微管成核中的γ-微管蛋白(γ-tubulin)。这呼应翟中和第十章关于成核是限速步骤及成核因子的内容。","page":9,"level":"掌握","img":"assets/img/ch07/p009.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":9,"sec":"0.60μM              ","title":"Arp2/3复合体：细胞中促进微丝组装","notes":"Actin nucleation by the Arp2/3 complex or the formins.\nArp2 and Arp3, each of which is about 45% identical to actin,\nnucleates F-actin growth from the (-) end, allowing rapid\nelongation at the (+) end.\nArp2/3复合体可以促进微丝装配时●actin的成核过程；●形成微\n丝70●侧支等。普遍存在于不同真核细胞中，亚基高度保守。\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.1 微丝的装配 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是Arp2/3复合体促进微丝组装。其中Arp2和Arp3各自与肌动蛋白约45%相同，可从(−)端为F-actin成核，使(+)端得以快速延长。原文中文指出：Arp2/3复合体可促进微丝装配时actin的成核过程，并能形成微丝70°侧支。该复合体普遍存在于不同真核细胞中，且各亚基高度保守。对应翟中和第十章微丝成核与分支网络的内容，是理解细胞皮层微丝网络的关键。","page":10,"level":"掌握","img":"assets/img/ch07/p010.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[{"id":"ch07_judge_1","modI":1,"q":"细胞中所有的微丝均为动态结构。（          ）","a":"错","e":"体内有些微丝并不是动态的结构，而是永久性的结构，如肌肉中的细丝及肠上皮细 胞微绒毛中的轴心微丝。","kp":"ch07_s1_2"}],"fill":[{"id":"ch07_fill_1","modI":1,"q":"微丝是由 G-actin 单体形成的多聚体，肌动蛋白单体具有极性，装配时呈头尾相接，故微 丝具有______。正极与负极都能生长，生长快的一端为______，慢的一端为______。","a":"极性；正极；负极","kp":"ch07_s1_4"},{"id":"ch07_fill_2","modI":1,"q":"同微丝相同，微管的装配也具有______。","a":"极性","kp":"ch07_s1_2"},{"id":"ch07_fill_3","modI":1,"q":"微管正极端的蛋白是______，微丝正极端的特点是______。","a":"β-微管蛋白；具有结合 ATP 的位点","kp":"ch07_s1_4"}],"short":[],"calc":[],"term":[]},{"i":2,"name":"第二节 微丝 · 2.2 微丝结合蛋白","slides":[{"i":10,"sec":"2.2.1 之一(actin-bindi","title":"2.2 微丝结合蛋白","notes":"2.2.1 之一(actin-binding proteins, ABP)\n维持非肌细胞中高浓度的单体肌动蛋白\n调节微丝长度，抑制已存在微丝生长，使细胞内有大量较短\n微丝存在。\n网络结构。如微绒毛中微丝束\n引起微丝骨架快速解聚为G-actin单体\n【结合课本/笔记】◆影响微丝装配动态性的药物对细胞都有毒害，说明微丝功能的发挥依赖于微丝与肌动蛋白单体库间的动态平衡。这种动态平衡受actin单体浓度和微丝结合蛋白的影响。","page":11,"level":"掌握","img":"assets/img/ch07/p011.jpg","anim":null,"fig":null,"points":["单体隔离蛋白(monomer-sequestering-protein):","封端(加帽)蛋白[end-blocking (capping) protein]：","交联蛋白(cross-linking protein) ：使细胞内多个微丝交联形成","纤维割断蛋白(filament-severing protein)","微丝解聚蛋白(filament-depolymerizition protein):","膜结合蛋白(membrane-binding protein)"],"check":{"q":"关于「微丝结合蛋白」，下列说法正确的是（　）","o":["A. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","B. 微丝是由G-actin单体形成的多聚体","C. 单体隔离蛋白(monomer-sequestering-protein):","D. Myosin I 重链无α-螺旋序"],"a":"C","e":"本页要点：单体隔离蛋白(monomer-sequestering-protein):","oe":["骨骼肌收缩单位肌原纤维属肌肉收缩内容，非微丝结合蛋白。","微丝由G-actin聚合是微丝本身的描述，非结合蛋白。","正确——单体隔离蛋白结合G-actin单体，抑制其聚合。","Myosin I重链结构属肌球蛋白，不是微丝结合蛋白。"]},"cards":null},{"i":11,"sec":"2.2.1 之一(actin-bindi","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• formin —— 形成蛋白(成核并随正端生长)\n• ARP complex —— ARP 复合物(成核成网、结合负端)\n• thymosin —— 胸腺素(结合亚基、阻止组装)\n• profilin —— 前纤维蛋白(结合亚基、加速延伸)\n• cofilin —— 切丝蛋白(结合ADP-肌动蛋白丝、促解聚)\n• tropomyosin —— 原肌球蛋白(稳定微丝)\n• gelsolin —— 凝溶胶蛋白(切断微丝、结合正端)\n• capping protein —— 加帽蛋白(阻止正端组装/解聚)\n• fimbrin/α-actinin/filamin/spectrin/ERM —— 丝束蛋白/α-辅肌动蛋白/细丝蛋白/血影蛋白/ERM(成束、交联、连膜)\n• actin subunits / actin filament —— 肌动蛋白亚基 / 肌动蛋白丝\n• plasma membrane —— 质膜\n【读图讲解】\n图解微丝组装与调控：肌动蛋白亚基与微丝(+/-端)，结合蛋白 formin/ARP 促核化、thymosin 阻止组装、profilin 加速延伸、cofilin 促解聚、gelsolin 切割、capping protein 封端、tropomyosin 稳定；fimbrin/α-actinin/filamin/spectrin/ERM 介导成束、交联与膜连接。考点：各微丝结合蛋白的功能与±端极性。","page":12,"level":"掌握","img":"assets/img/ch07/p012.jpg","anim":null,"fig":null,"points":["formin","ARPcomplex","nucleatesassemblyandremalns","nucleates assembly","assoclatedwiththegrowing","toformawebandremalns","plus end","assoclatedwiththemlnusend"],"check":null,"cards":null},{"i":12,"sec":"2.2.1 之一(actin-bindi","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• A/B/C —— 微丝交联三式：紧密平行束(fimbrin)、较宽平行束(α-actinin)、直角交叉网(filamin)\n• Arp2/Arp3 —— Arp2/3 复合物(从母丝侧面核化分支)\n• capping protein —— 加帽蛋白(封端终止延伸)\n【读图讲解】\n模式图示微丝交联：fimbrin(丝束蛋白)使微丝紧密平行成束；α-actinin(α-辅肌动蛋白)形成较宽平行束；filamin(细丝蛋白)使微丝直角交叉成网；并示 Arp2/3 从母丝侧面核化出分支、加帽蛋白封闭＋端终止延伸。考点：交联方式差异与分支成核。","page":13,"level":"掌握","img":"assets/img/ch07/p013.jpg","anim":null,"fig":null,"points":["细丝蛋白","丝束蛋白","α-辅肌动蛋白","加帽蛋白","肌动蛋白","Arp2","Arp3","Arp2/3复合物"],"check":null,"cards":null},{"i":13,"sec":"2.2.1 之一(actin-bindi","title":"之二：微丝的马达蛋白(motor protein)","notes":"－肌球蛋白(myosin)\napproximately 40 myosins encoded by the human genome\n肌肉收缩、胞质分裂\nThree common classes of myosin.\n【结合课本/笔记】一、高尔基体的形态结构● 电镜下高尔基体结构是由扁平膜囊和大小不等的囊泡构成● 高尔基体是有极性的细胞器：位置、方向、物质转运与生化极性● 高尔基体各部膜囊的４种标志细胞化学反应：● 高尔基体至少由互相联系的4个部分组成，每一部分又可能划分出更精细的间隔● 高尔基体与细胞骨架关系密切，在非极性细胞中，高尔基体分布在MTOC(负端)● 高尔基的膜囊上存在微管的马达蛋白（cytoplasmic dynein和kinesin）和微丝的马达蛋白（myosin）。最近还发现特异的血影蛋白（spectrin）网架 。它们在维持高尔基体动态的空间结构以及复杂的膜泡运输中起重要的作用。\n\n【本页英文讲解】\n本页进入微丝的马达蛋白(motor protein)——肌球蛋白(myosin)。原文指出，人类基因组编码约40种肌球蛋白(approximately 40 myosins)，并提及三类常见的肌球蛋白(three common classes)。肌球蛋白参与肌肉收缩、胞质分裂等重要过程。可见肌球蛋白是一个庞大的超家族，不同成员承担不同功能。对应翟中和第十章“微丝结合蛋白与马达蛋白”的内容，是理解微丝产生运动的起点。","page":14,"level":"掌握","img":"assets/img/ch07/p014.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":14,"sec":"2.2.1 之一(actin-bindi","title":"The myosin","notes":"superfamily in\nhumans.\nComputer\nanalysis of the\nrelatedness of S1\nhead domains of all\nof the\napproximately 40\nmyosins encoded by\nthe human genome.\nEach myosin is\nindicated by a line.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.2 微丝结合蛋白 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是人类的肌球蛋白超家族(myosin superfamily in humans)。原文说明这是通过对人类基因组编码的约40种肌球蛋白的S1头部结构域(S1 head domains)进行相关性分析(computer analysis of the relatedness)得出的结果，每种肌球蛋白在图中用一条线表示。可见，尽管肌球蛋白种类众多，判断其亲缘关系主要依据保守的头部结构域。对应翟中和第十章关于肌球蛋白家族分类的内容，可作为理解该家族多样性的背景材料。","page":15,"level":"掌握","img":"assets/img/ch07/p015.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":15,"sec":"2.2.1 之一(actin-bindi","title":"所有myosin分子","notes":"都有相似的马达\n结构域，但C-端\n和N端多样\n【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":16,"level":"掌握","img":"assets/img/ch07/p016.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":16,"sec":"2.2.1 之一(actin-bindi","title":"三种肌球蛋白的结构比较","notes":"列, 单体.\n二聚体, 其每条重链的尾部螺\n旋盘绕在一起, 形成 a rodlike\ncoiled-coil sturcture\n与肌肉收缩滑动、胞质分\n裂\n或细胞内膜系统结合, 参与\n细胞骨架与细胞膜的相互作\n用(membrane-related\nactivities) eg.膜泡运输等","page":17,"level":"掌握","img":"assets/img/ch07/p017.jpg","anim":null,"fig":null,"points":["Myosin I 重链无α-螺旋序","Myosin II & myosin V都是","Myosin II主要功能是参","Myosin I&V尾部与质膜"],"check":{"q":"关于「种肌球蛋白的结构比较」，下列说法正确的是（　）","o":["A. Myosin I 重链无α-螺旋序","B. 细胞信号转导","C. Rapid disassembly and reassembly of","D. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;"],"a":"A","e":"本页要点：Myosin I 重链无α-螺旋序","oe":["正确——肌球蛋白I重链无α-螺旋尾部，不能形成双头纤维。","细胞信号转导与肌球蛋白的结构比较无关。","微丝快速解聚与重组装属微丝动态性，非肌球蛋白结构。","actin极性属微丝装配特征，非肌球蛋白的结构比较。"]},"cards":null},{"i":17,"sec":"2.2.1 之一(actin-bindi","title":"肌肉收缩系统中:","notes":"肌球蛋白(myosin II)-肌肉总量的一半, 已发现十多种\n2结合位点(ATP-binding site, actin-binding site), 产生能\n量, 最保守区域; 所有myosin头部都是一个ATPase, 水解ATP,\n并且ATPase活性actin-activated\nlight chains, 调节头部的活性(activity)\n特异性区域(determine the specific role of particular\nmyosin), 根据各自不同的功能结合不同的东西\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.2 微丝结合蛋白 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌肉收缩系统中的肌球蛋白(myosin II)，约占肌肉总量的一半，已发现十多种。其结构分三部分：头部(head domain)含ATP结合位点(ATP-binding site)和肌动蛋白结合位点(actin-binding site)，是产生能量、最保守的区域，所有myosin头部都是ATPase，且其ATPase活性受actin激活(actin-activated)；颈部(neck region)为α-螺旋，结合轻链(light chains)调节头部活性；尾部(tail domain)为特异性区域，决定各myosin的具体功能并据此结合不同对象。","page":18,"level":"掌握","img":"assets/img/ch07/p018.jpg","anim":null,"fig":null,"points":["头部(head domain)","颈部(α-helical neck region): α-螺旋, associated with the","尾部(tail domain)"],"check":{"q":"关于「肌肉收缩系统中:」，下列说法正确的是（　）","o":["A. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","B. 头部(head domain)","C. 微丝是由G-actin单体形成的多聚体","D. Myosin I 重链无α-螺旋序"],"a":"B","e":"本页要点：头部(head domain)","oe":["肌原纤维是骨骼肌的收缩单位，属收缩结构的总体描述。","正确——肌球蛋白头部具ATP酶活性，是与肌动蛋白结合的位点。","微丝由G-actin聚合属微丝基本成分，非收缩系统要点。","Myosin I结构属肌球蛋白类型比较，非肌肉收缩系统。"]},"cards":null},{"i":18,"sec":"2.2.1 之一(actin-bindi","title":"Myosin II","notes":"【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":19,"level":"掌握","img":"assets/img/ch07/p019.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":19,"sec":"2.2.1 之一(actin-bindi","title":"The myosin head","notes":"uses ATP to pull on\nan actin filament.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.2 微丝结合蛋白 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌球蛋白头部(the myosin head)的作用机制。原文一句话概括：肌球蛋白头部利用ATP在肌动蛋白丝(actin filament)上拉动(uses ATP to pull on an actin filament)。也就是说，肌球蛋白头部水解ATP释放能量，产生构象变化，从而沿微丝定向“行走”并牵引微丝。这是肌肉收缩和多种细胞运动的动力来源。对应翟中和第十章肌球蛋白作为微丝马达蛋白的力学机制，是理解滑动学说的关键环节。","page":20,"level":"掌握","img":"assets/img/ch07/p020.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":20,"sec":"2.2.1 之一(actin-bindi","title":"Myosin体外运动实验模式图","notes":"纯化的myosin头部固定在盖玻片上，体系中加入荧光标记的\n微丝，当加入ATP时，荧光显微镜下可以观察到微丝在玻片\n上的滑动。","page":21,"level":"掌握","img":"assets/img/ch07/p021.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_mcq_4","mod":"2.2 微丝结合蛋白","modI":2,"q":"关于肌动蛋白的叙述错误的是（         ）。","o":["A．G-肌动蛋白与 F-肌动蛋白可互相转变","B．肌动蛋白上有肌球蛋白结合位点，但无二价阳离子的结合位点","C．F______肌动蛋白的聚合过程不需能量","D．肌动蛋白是微丝的基础蛋白质"],"a":"B","e":"B 选项肌动蛋白有 ATP 结合位点和 Mg2 结合位点。 ＋","kp":"ch07_s2_18","oe":["G-肌动蛋白与F-肌动蛋白可互相转变，此叙述正确，故不选。","正确——肌动蛋白有ATP及Mg2+结合位点，说其无二价阳离子位点错误。","F-肌动蛋白的聚合需ATP供能，该叙述正确，故不选。","肌动蛋白是微丝的基础蛋白质，此叙述正确，故不选。"]},{"id":"ch07_mcq_5","mod":"2.2 微丝结合蛋白","modI":2,"q":"下列物质中，能抑制微丝解聚的是（           ）。","o":["A．秋水仙素","B．紫杉醇","C．鬼笔环肽","D．细胞松弛素 B"],"a":"C","e":"A 项，秋水仙素能抑制微管的组装，而不影响其解聚。B 项，紫衫醇能抑制微管的 解聚，而不影响其组装。D 项，细胞松弛素 B 能抑制微丝的组装，而不影响其解聚。","kp":"ch07_s2_10","oe":["秋水仙素抑制微管的组装，不影响微丝的解聚。","紫杉醇抑制微管的解聚，作用于微管而非微丝。","正确——鬼笔环肽与F-actin结合，稳定微丝并抑制其解聚。","细胞松弛素B抑制微丝的组装，而非抑制微丝解聚。"]}],"judge":[],"fill":[],"short":[{"id":"ch07_short_2","modI":2,"q":"影响微丝装配的因素有哪些？","a":"影响微丝装配的因素包括： （1）微丝的装配受肌动蛋白临界浓度的影响。在正常的体外条件下，单体的临界浓度（critical concentration，Cc）Cc 是 0.1mol／L。高于该值，G-肌动蛋白倾向于聚合，低于该值，F\"肌 动蛋白将会解聚。所以 Cc 可用它来测定溶液中 G-肌动蛋白聚合的能力。 （2）在肌动蛋白纤维的装配过程还受一些离子浓度的影响。例如，向 G 肌动蛋白溶液中添 加 Mg2 、K 、Na ，可诱导 p 肌动蛋白聚合成 F-肌动蛋白。该过程是可逆的，当这些离子 ＋     ＋   ＋   的浓度较低时，F-肌动蛋白趋于去聚合，而在 Mg2 和高浓度 K 或 Na 的溶液诱导下，G- ＋  ＋  ＋   肌动蛋白则装配成纤维状肌动蛋白。","kp":"ch07_s2_10"},{"id":"ch07_short_3","modI":2,"q":"简述微丝的形态和化学组成。","a":"微丝是一种普遍存在于真核细胞中的实心纤维，其直径约为 6nm，常成群或成束存在于 胞质内。在高度持化的细胞，如肌细胞能形成稳定的结构，但更常见的是在非肌细胞内形成 不稳定的束或复杂的网。微丝主要由 3 类蛋白质组成，一类是肌动蛋白，是微丝的基础蛋白； 另一类是肌球蛋 A，肌球蛋白和肌动蛋白共同作为收缩蛋白在收缩中起主要作用，还有一类 是肌动蛋白一结合蛋白，已经发现这类结合蛋白有 40 多种，它们在微丝中具有不同的功能， 与肌动蛋白纤维的结合、聚合及稳定等作用有关。","kp":"ch07_s2_13"}],"calc":[],"term":[{"id":"ch07_term_1","modI":2,"term":"肌球蛋白（myosin）。","def":"肌球蛋白（myosin）是微丝的化学组成之一，有 1 杆部和 2 个头部，每个头部 2 条轻链， 具有 ATP 酶活性。头部具有肌动蛋白结合点，可与肌动蛋白结合，在粗肌丝中作为一种收 缩蛋白参与肌肉收缩活动。","kps":"","kp":"ch07_s2_18"}]},{"i":3,"name":"第二节 微丝 · 2.3 微丝特异性药物(Specific drug for MF)","slides":[{"i":21,"sec":"2.3 微丝特异性药物(Specific","title":"2.3 微丝特异性药物(Specific drug for MF)","notes":"I 细胞松弛素\nend of MF, inhibit the polymerization of actin.)\nII 鬼笔环肽(philloidin)\n(a double ring bar peptide secreted by Amanita Phallodies)\n(had high affinity with MF, inhibited the disassemble of MF,\nstabilized MF.)\n(only binding with f-actin/MF, but not with G-actin, can be a tag\nof MF in cell.)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.3 微丝特异性药物(Specific drug for MF) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 细胞松弛素（cytochalasins）：真菌产生的一种代谢物（生物碱），可以切断微丝并结合在微丝（+）端，阻抑肌动蛋白聚合，但对解聚没有影响。\n\n【本页英文讲解】\n本页主题是微丝特异性药物(specific drug for MF)。I. 细胞松弛素(cytochalasin)：是真菌的一种代谢产物，能切断微丝、结合于微丝末端从而阻抑actin聚合，破坏微丝的网络结构。II. 鬼笔环肽(phalloidin)：毒蕈(鹅膏菌)产生的双环杆肽，与微丝有强亲合力，能稳定微丝、抑制其解聚；它只与F-actin/MF结合而不与G-actin结合，故可用来标记细胞中的微丝。对应翟中和第十章微丝药物，是常考知识点。","page":22,"level":"掌握","img":"assets/img/ch07/p022.jpg","anim":null,"fig":null,"points":["真菌的一种代谢产物(metabolite of fungal)","切断微丝, 阻抑actin聚合(severing MF, and binding to the","破坏微丝的网络结构(destroy 3-D network of MF)","毒蕈产生的双环杆肽","与微丝有强亲合作用, 稳定微丝, 抑制解聚","只与F-actin/MF结合, 不与G-actin结合, 标记细胞中的微丝。"],"check":{"q":"关于「微丝特异性药物(Specific drug fo…」，下列说法正确的是（　）","o":["A. 原生动物中的变形虫，高等动物中的巨噬细","B. 真菌的一种代谢产物(metabolite of fungal)","C. An initial group of several subunits to associate correctly, to","D. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)"],"a":"B","e":"本页要点：真菌的一种代谢产物(metabolite of fungal)","oe":["变形虫、巨噬细胞属细胞爬行运动的内容，非微丝药物。","正确——细胞松弛素是真菌代谢产物，能切断微丝并抑制聚合。","若干单体正确结合指微丝聚合起始，不属于药物。","肌原纤维属骨骼肌收缩结构，不是微丝特异性药物。"]},"cards":null}],"mcq":[{"id":"ch07_mcq_2","mod":"2.3 微丝特异性药物(Specific drug for MF)","modI":3,"q":"用特异性药物细胞松弛素 B 可以阻断下列哪种小泡的形成？（        ）","o":["A．胞饮泡","B．吞噬泡","C．分泌小泡","D．包被小泡"],"a":"B","e":"吞噬泡的形成与细胞膜下富含肌动蛋白纤维的溶胶区域的状态转化有关，能为细胞 松弛素所抑制。","kp":"ch07_s3_21","oe":["胞饮泡形成与网格蛋白及膜内陷相关，不被细胞松弛素B阻断。","正确——吞噬泡形成依赖膜下肌动蛋白，可被细胞松弛素B抑制。","分泌小泡由高尔基体出芽形成，与微丝无关。","包被小泡由网格蛋白或COP包被形成，与微丝无关。"]}],"judge":[{"id":"ch07_judge_4","modI":3,"q":"细胞松弛素 B 是真菌的一种代谢产物，可阻止肌动蛋白的聚合，结合到微丝的正极，阻 止新的单体聚合，致使微丝解聚。（                     ）","a":"错","e":"细胞松弛素 B 是一种真菌的代谢产物，与微丝结合后可以将微丝切断，并结合在 微丝末端阻抑肌动蛋白在该部位的聚合，但对微丝的解聚没有明显影响，因而用细胞松弛素 B 处理细胞可以破坏微丝的网络结构，并阻止细胞的运动。","kp":"ch07_s3_21"}],"fill":[],"short":[],"calc":[],"term":[{"id":"ch07_term_2","modI":3,"term":"细胞松弛素（cytochalasin）。","def":"细胞松弛素是真菌的一类代谢产物，与微丝结合后可以将微丝切断，并结合在微丝末端 阻抑肌动蛋白在该部位的聚合，是微丝聚合的特异性抑制剂，常用的有细胞松弛素 B 和细 胞松弛素 D。","kps":"","kp":"ch07_s3_21"},{"id":"ch07_term_3","modI":3,"term":"鬼笔环肽（phalloidin）。","def":"鬼笔环肽是由鬼笔鹅膏真菌（Amanka phallodines）产生的一种环肽，对微丝表面具有 很强的亲和力，但不与肌动蛋白单体结合，对微丝的解聚有抑制作用，使微丝保持稳定状态。","kps":"","kp":"ch07_s3_21"}]},{"i":4,"name":"第二节 微丝 · 2.4 微丝的功能","slides":[{"i":22,"sec":"2.4 微丝的功能","title":"2.4 微丝的功能","notes":"●胞质环流(细胞内物质运输)：藻类、高等植物细\n胞中细胞质围绕中央大液泡进行的环形流动模式。\n●肌肉收缩 F-actin & myosin II\n●动物细胞变形运动/细胞迁移(cell migration)","page":23,"level":"掌握","img":"assets/img/ch07/p023.jpg","anim":null,"fig":null,"points":["细胞信号转导","细胞内物质运输","支架作用－维持细胞形态","细胞运动：","细胞的营养代谢，分配营养和代谢产物。","由actin和myosin相互作用引起的","动物细胞胞质分裂的收缩环：F-actin & myosin II"],"check":{"q":"关于「微丝的功能」，下列说法正确的是（　）","o":["A. Hair cells are named for the","B. 直径7nm 组成蛋白：球形肌动蛋白(G-actin)","C. 细胞信号转导","D. 真菌的一种代谢产物(metabolite of fungal)"],"a":"C","e":"本页要点：细胞信号转导","oe":["毛细胞的英文命名属静纤毛与听觉内容，非微丝功能。","7nm与G-actin是微丝的结构描述，非微丝的功能。","正确——微丝参与细胞信号转导，是微丝的功能之一。","真菌代谢产物指细胞松弛素，属微丝特异性药物。"]},"cards":null}],"mcq":[{"id":"ch07_mcq_3","mod":"2.4 微丝的功能","modI":4,"q":"构成微丝的基本成分是（         ）。","o":["A．肌动蛋白","B．肌球蛋白","C．肌钙蛋白","D．三者均有"],"a":"A","e":"微丝（microfilament，MF）的主要结构成分是肌动蛋白。B 项，肌球蛋白是依赖于 微丝的分子马达；C 项，肌钙蛋白是结合在横纹肌细肌丝上的调节蛋白，有三个亚基组成： 肌钙蛋白 T、肌钙蛋白 I 和肌钙蛋白 C。其中肌钙蛋白 T 能与原肌球蛋白结合，肌钙蛋白 I 能抑制肌球蛋白的 ATPase 活性，肌钙蛋白 C 能与钙离子结合。","kp":"ch07_s4_22","oe":["正确——微丝的主要结构成分是肌动蛋白。","肌球蛋白是依赖微丝的马达蛋白，不是微丝的组成成分。","肌钙蛋白是横纹肌细肌丝上的调节蛋白，非微丝基本成分。","三者并非都是微丝成分，微丝基本成分只有肌动蛋白。"]}],"judge":[{"id":"ch07_judge_5","modI":4,"q":"秋水仙碱可同微丝的（＋）端结合，并阻止新的单体加入。（                         ）","a":"错","e":"秋水仙碱能与微管蛋白亚基结合，具有抑制微管组装的作用。细胞松弛素和鬼笔环 肽是影响微丝组装的特异性药物。","kp":"ch07_s4_22"},{"id":"ch07_ajudge_3","modI":4,"q":"细胞信号转导","a":"对","e":"本页要点：细胞信号转导","kp":"ch07_s4_22"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":5,"name":"第二节 微丝 · 2.4.1 胞质环流","slides":[{"i":23,"sec":"2.4.1      胞质环流","title":"2.4.1      胞质环流","notes":"Cytoplasmic streaming in cylindrical giant algae.\nA large vesicle connected to an\nunderlying bundle of F-actin.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 胞质环流 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是胞质环流(cytoplasmic streaming)。原文以圆柱形巨大藻类(cylindrical giant algae)为例，图示一个大囊泡(large vesicle)与下方一束F-actin相连。胞质环流依赖微丝与肌球蛋白的相互作用，驱动细胞质定向流动，从而帮助物质运输。对应翟中和第十章微丝参与的细胞运动，属于微丝功能的经典实例，常与细胞松弛素抑制实验一起考查。","page":24,"level":"掌握","img":"assets/img/ch07/p024.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_1","mod":"第二节 微丝 · 2.4.1 胞质环流","modI":5,"q":"关于「胞质环流」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. Cytoplasmic streaming in cylindrical giant algae.","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"B","e":"本页要点：Cytoplasmic streaming in cylindrical giant algae.","kp":"ch07_s5_23","oe":["描述微丝直径与组成，与胞质环流现象无关，故不选","胞质环流见于筒状巨藻，由肌动蛋白微丝驱动，正确","描述微丝组成，未说明胞质环流，故不选","描述微丝动态装配，与胞质环流无直接关系，故不选"]}],"judge":[{"id":"ch07_ajudge_2","modI":5,"q":"Cytoplasmic streaming in cylindrical giant algae.","a":"对","e":"本页要点：Cytoplasmic streaming in cylindrical giant algae.","kp":"ch07_s5_23"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":6,"name":"第二节 微丝 · 2.4.2 sliding of myo","slides":[{"i":24,"sec":"2.4.2 sliding of myo","title":"⎯脊椎动物的跑、跳、走、游泳和飞翔都依赖与骨骼肌强","notes":"2.4.2 sliding of myosin II and actin filaments\ncauses muscles to contract\n有力地收缩并带动不同的骨骼。\n心肌和平滑肌的收缩。\n肌细胞(muscle cells)\n许多细胞运动都来自actin+myosin的相互作用\n(many cell movements-from the locomotion of whole\ncells to the motion of components inside cells-depend\non the interaction of actin and myosin.)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.2 sliding of myo ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌球蛋白II与肌动蛋白丝的滑动引起肌肉收缩(sliding of myosin II and actin filaments causes muscles to contract)。原文指出，脊椎动物的跑、跳、走、游泳和飞翔都依赖骨骼肌强有力收缩并带动不同骨骼；心脏跳动及胃肠、子宫、动脉的缓慢持久蠕动则依赖心肌和平滑肌收缩。许多细胞运动(从整个细胞移动到细胞内部成分的运动)都来自actin与myosin的相互作用。对应翟中和第十章肌肉收缩的滑动学说。","page":25,"level":"掌握","img":"assets/img/ch07/p025.jpg","anim":null,"fig":null,"points":["心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖"],"check":{"q":"关于「⎯脊椎动物的跑、跳、走、游泳和飞翔都依赖与骨骼肌…」，下列说法正确的是（　）","o":["A. 心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","B. 微丝是由G-actin单体形成的多聚体","C. Myosin I 重链无α-螺旋序","D. 细胞信号转导"],"a":"A","e":"本页要点：心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","oe":["正确——心脏搏动与胃肠子宫蠕动依赖平滑肌的缓慢持久收缩。","微丝由G-actin聚合属微丝的基本结构，非肌肉类型。","Myosin I结构属肌球蛋白类型比较，非肌肉类型区别。","细胞信号转导属微丝功能，非肌肉类型的区分。"]},"cards":null},{"i":25,"sec":"2.4.2 sliding of myo","title":"Heart muscle cell","notes":"Thin filaments (actin)\nThe heart is the most\nheavily worked muscle in\nthe body, contracting about\n3 billion (3×109) times\nduring the course of a\nhuman lifetime.\nThick filaments(myosin)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.2 sliding of myo ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是心肌细胞(heart muscle cell)。图中细丝(thin filaments)是肌动蛋白(actin)，粗丝(thick filaments)是肌球蛋白(myosin)。原文指出，心脏是人体中工作最繁重的肌肉，一生中约收缩30亿次(3×10⁹次)。由此可见心肌对能量和结构稳定性的要求极高。对应翟中和第十章由肌动蛋白与肌球蛋白组成的肌肉收缩装置，可作为理解心肌和平滑肌收缩的背景。","page":26,"level":"掌握","img":"assets/img/ch07/p026.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":26,"sec":"2.4.2 sliding of myo","title":"cardiac(心脏的) myosin","notes":"Effect on the heart of a subtle mutation in\n肌球蛋白的微小变化也\n会造成心脏的严重疾病，\n如家族性的肥厚型心肌\n病，青年运动员猝死的\n遗传性疾病。\ncontrol          mutation\nControl: normal heart from a 6-day old mouse pup.\nMutation: heart from a pup with a point mutation in both copies\nof its cardiac myosin gene, changing Arg 403 to Gln. Both\natria(心房) are greatly enlarged (hypertrophic), and the mice die\nwithin a few weeks of birth.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.2 sliding of myo ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是心肌肌球蛋白(cardiac myosin)微小突变对心脏的影响。原文图注显示：对照(control)为6天龄小鼠正常心脏；突变(mutation)小鼠心脏肌球蛋白基因两个拷贝均发生点突变，使第403位精氨酸(Arg 403)变为谷氨酰胺(Gln)，结果两个心房(atri)显著增大(hypertrophic)，小鼠在出生后数周内死亡。中文提示指出，肌球蛋白的微小变化可造成心脏严重疾病，如家族性肥厚型心肌病，是青年运动员猝死的遗传性疾病。","page":27,"level":"掌握","img":"assets/img/ch07/p027.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_4","mod":"第二节 微丝 · 2.4.2 sliding of myo","modI":6,"q":"关于「sliding of myo」，下列说法正确的是（　）","o":["A. 心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"A","e":"本页要点：心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","kp":"ch07_s6_24","oe":["正确——平滑肌肌球蛋白沿微丝滑动，产生心脏搏动与胃肠蠕动。","微丝7nm与G-actin属微丝结构，非肌球蛋白滑动。","微丝由G-actin聚合属微丝基本结构，非肌球蛋白滑动。","微丝动态装配属微丝的动态性，非肌球蛋白滑动。"]}],"judge":[{"id":"ch07_ajudge_5","modI":6,"q":"心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","a":"对","e":"本页要点：心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","kp":"ch07_s6_24"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":7,"name":"第二节 微丝 · 2.4.2 肌肉收缩","slides":[{"i":27,"sec":"2.4.2 肌肉收缩","title":"2.4.2 肌肉收缩","notes":"它由2种类型的长纤维构成：\n●粗肌丝-肌球蛋白 myosin II\n●细肌丝-肌动蛋白 actin(主)+原肌球蛋白+\n肌钙蛋白\n【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":28,"level":"掌握","img":"assets/img/ch07/p028.jpg","anim":null,"fig":null,"points":["骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)"],"check":{"q":"关于「肌肉收缩」，下列说法正确的是（　）","o":["A. 细胞信号转导","B. Rapid disassembly and reassembly of","C. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;","D. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)"],"a":"D","e":"本页要点：骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","oe":["细胞信号转导属微丝的功能，与肌肉收缩无关。","微丝快速解聚与重组装属微丝动态性，非肌肉收缩。","actin极性属微丝装配特征，非肌肉收缩机制。","正确——骨骼肌的收缩单位是肌原纤维，由粗、细肌丝组成。"]},"cards":null},{"i":28,"sec":"2.4.2 肌肉收缩","title":"Structure of the skeletal muscle sarcomere.","notes":"Skeletal muscles consist of muscle fibers\nmade of bundles of multinucleated cells.\nEach cell contains a bundle of myofibrils,\nwhich consist of thousands of repeating\ncontractile structures called sarcomeres.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.2 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环由大量反向平行排列的微丝组成，其收缩机制是肌动蛋白和肌球蛋白相对滑动。肌肉收缩(muscle contraction)肌肉可看作一种特别富含细胞骨架的效力非常高的能量转换器，它直接将化学能转变为机械能。◆肌肉的细微结构(以骨骼肌为例)\n\n【本页英文讲解】\n本页主题是骨骼肌肌节(sarcomere)的结构。原文说明：骨骼肌由肌纤维(muscle fibers)构成，肌纤维由多核细胞(multinucleated cells)成束组成；每个细胞含一束肌原纤维(myofibrils)，肌原纤维又由成千上万个重复的收缩结构——肌节(sarcomeres)组成。肌节是骨骼肌收缩的基本单位，其重复排列形成横纹。对应翟中和第十章横纹肌的肌节结构，是理解肌肉收缩滑动学说的解剖学基础。","page":29,"level":"掌握","img":"assets/img/ch07/p029.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":29,"sec":"2.4.2 肌肉收缩","title":"典型的肌细胞是圆柱形多核长细胞，在细胞质中有成","notes":"束的肌原纤维(myofibril)。\n\n【读图讲解】\n本图为典型肌细胞(肌纤维)的立体模式图。细胞呈长圆柱形、多核，表面为肌膜(Sarcolemma)，多个细胞核(Nucleus)位于细胞周边。胞质中充满成束的肌原纤维(Myofibrils)，具明暗相间的横纹，并标出Z盘(Z disk)。肌原纤维间包绕肌质网(Sarcoplasmic reticulum)，横小管(Transverse tubule)由肌膜内陷形成。图下文字指出：典型肌细胞是圆柱形多核长细胞，胞质中有成束的肌原纤维。要点：掌握肌纤维多核、横纹、肌质网、横小管等结构及Z盘的位置。","page":30,"level":"掌握","img":"assets/img/ch07/p030.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":30,"sec":"2.4.2 肌肉收缩","title":"肌肉收缩系统中的微丝结合蛋白","notes":"1) myosin II-粗肌丝\n2) 原肌球蛋白(tropomyosin, Tm):肌肉细肌丝中actin的结合蛋\n白，封闭actin and myosin头部的结合\n3) 肌钙蛋白(troponin, Tn)\n含3个亚基，其中●Tn-C: 特异地与Ca2+结合;高浓度的\nCa2+解除Tm对actin的抑制；●Tn-T: 与原肌球蛋白Tm\n有高度亲和力;\n【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":31,"level":"掌握","img":"assets/img/ch07/p031.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":31,"sec":"2.4.2 肌肉收缩","title":"3-dimensional electron-microscopic reconstructions of the TM","notes":"helix (yellow) on a thin filament (F-actin) from scallop muscle.\nTm in its “off” state shifts to the “on” state when the Ca2+\nconcentration increases.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.2 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 微丝功能◆维持细胞形态，赋予质膜机械强度◆细胞运动◆微绒毛(microvillus)◆应力纤维(stress fiber)◆参与胞质分裂◆肌肉收缩(muscle contraction)\n\n【本页英文讲解】\n本页主题是原肌球蛋白(tropomyosin, TM)螺旋在细丝上的三维电镜重建(3-dimensional electron-microscopic reconstructions)。原文以扇贝(scallop)肌肉的细丝(F-actin)为例，黄色为TM螺旋，它覆盖在细丝上。当Ca²⁺浓度升高时，TM由“关”状态(off state)转变为“开”状态(on state)，从而暴露肌动蛋白上的结合位点。对应翟中和第十章横纹肌收缩的钙调节机制，是Ca²⁺调控收缩的重要考点。","page":32,"level":"掌握","img":"assets/img/ch07/p032.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_6","mod":"第二节 微丝 · 2.4.2 肌肉收缩","modI":7,"q":"关于「肌肉收缩」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. 微丝是由G-actin单体形成的多聚体","C. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"C","e":"本页要点：骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","kp":"ch07_s7_27","oe":["微丝7nm与G-actin属微丝结构，非肌肉收缩单位。","微丝由G-actin聚合属微丝基本结构，非肌肉收缩单位。","正确——骨骼肌细胞的收缩单位是肌原纤维，由粗、细肌丝组成。","微丝动态装配属微丝的动态性，非肌肉收缩单位。"]}],"judge":[{"id":"ch07_judge_3","modI":7,"q":"α、β、和γ三种类型的肌动蛋白都存在于肌细胞中。（                  ）","a":"错","e":"只有α-肌动蛋白存在于肌细胞中。","kp":"ch07_s7_27"},{"id":"ch07_ajudge_7","modI":7,"q":"骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","a":"对","e":"本页要点：骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","kp":"ch07_s7_27"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":8,"name":"第二节 微丝 · 2.4.1 肌肉收缩","slides":[{"i":32,"sec":"2.4.1 肌肉收缩","title":"2.4.1 肌肉收缩","notes":"来自脊髓运动神经元的神经冲动\n→轴突传递\n肌肉细胞膜去极化(动作电位产生)\n→质膜向cytosol内陷所形成的横管T-小管,其末端靠近ER\n肌质网: 肌细胞中特化的光面内质网(钙库)，\n释放Ca2+至肌浆中\nCa2+/肌钙蛋白Tn结合引起构象变化●解除原肌球蛋白(Tm)\n对actin的抑制，使actin与myosin头部结合。\nActin/myosin相对滑动:水解ATP, 化学能转化为机械能; If Ca2+\nstill 存在继续下一个循环, myosin沿肌动蛋白细丝滑动\nCa2+回收:神经冲动一经停止, 肌质网主动运输回收Ca2+, 收缩周\n期停止。","page":33,"level":"掌握","img":"assets/img/ch07/p033.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":33,"sec":"2.4.1 肌肉收缩","title":"The sarcoplasmic reticulum","notes":"regulate the cytosolic Ca2+\nlevel in skeletal muscle\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是肌质网(sarcoplasmic reticulum)。原文指出，肌质网负责调节骨骼肌(skeletal muscle)细胞质中的Ca²⁺水平(regulate the cytosolic Ca²⁺ level)。肌质网储存Ca²⁺，在神经冲动到来时释放Ca²⁺引起收缩，随后又回收Ca²⁺使肌肉舒张。因此肌质网是肌肉收缩—舒张周期中Ca²⁺信号的关键细胞器。对应翟中和第十章横纹肌收缩的兴奋—收缩偶联机制，常与肌钙蛋白、原肌球蛋白一起考查。","page":34,"level":"掌握","img":"assets/img/ch07/p034.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":34,"sec":"2.4.1 肌肉收缩","title":"striated muscle(横纹肌)","notes":"The sliding-filament model of contraction in\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 微丝功能◆维持细胞形态，赋予质膜机械强度◆细胞运动◆微绒毛(microvillus)◆应力纤维(stress fiber)◆参与胞质分裂◆肌肉收缩(muscle contraction)\n\n【本页英文讲解】\n本页主题是横纹肌(striated muscle)收缩的滑动丝模型(sliding-filament model of contraction)。该模型认为，肌肉收缩时粗丝(肌球蛋白)与细丝(肌动蛋白)本身长度并不缩短，而是通过肌球蛋白头部与肌动蛋白丝的相对滑动，使粗细丝相互滑入，肌节缩短，从而整块肌肉收缩。对应翟中和第十章肌肉收缩的滑动学说，是本部分最核心的考点之一，常要求解释其基本要点。","page":35,"level":"掌握","img":"assets/img/ch07/p035.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":35,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"2.4. 2 非肌细胞中高度有序排列的微丝束","notes":"－肠上皮细胞微绒毛内\n外突起，形成大量微绒毛(microvilli), 扩大了吸收面\n积。\n束之间由微丝结合蛋白(eg. fimbrin, villin)连在一起\n(cross-link), 形成一种稳固的结构, enable it to\nmaintain its long, slender shape.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环由大量反向平行排列的微丝组成，其收缩机制是肌动蛋白和肌球蛋白相对滑动。肌肉收缩(muscle contraction)肌肉可看作一种特别富含细胞骨架的效力非常高的能量转换器，它直接将化学能转变为机械能。◆肌肉的细微结构(以骨骼肌为例)\n\n【本页英文讲解】\n本页主题是肠道上皮(gut epithelium)中的肌动蛋白丝(actin filaments)。原文内容极简，仅给出这一主题。上皮细胞顶端的微绒毛等结构富含肌动蛋白丝，它们起支撑和维持细胞形态的作用。可联系翟中和第十章微丝在非肌细胞中的功能：微丝常与细胞膜相连，参与维持细胞表面特殊结构(如微绒毛)。原文残缺，故只解释到这里。","page":36,"level":"掌握","img":"assets/img/ch07/p036.jpg","anim":null,"fig":null,"points":["肠上皮细胞(intestinal epithelial cells)表面细胞膜向","维持微绒毛形状的-内部同向平行的轴心微丝, 微丝"],"check":{"q":"关于「非肌细胞中高度有序排列的微丝束」，下列说法正确的是（　）","o":["A. 原生动物中的变形虫，高等动物中的巨噬细","B. An initial group of several subunits to associate correctly, to","C. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","D. 肠上皮细胞(intestinal epithelial cells)表面细胞膜向"],"a":"D","e":"本页要点：肠上皮细胞(intestinal epithelial cells)表面细胞膜向","oe":["变形虫、巨噬细胞属细胞爬行运动的内容。","该英文指微丝聚合起始，非微丝束的排列描述。","肌原纤维属骨骼肌收缩结构，非非肌细胞微丝束。","正确——肠上皮细胞微绒毛含高度有序的微丝束，稳定细胞膜突起。"]},"cards":null},{"i":36,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Absorptive epithelial cells —— 吸收性上皮细胞\n• Microvilli —— 微绒毛\n• Basal lamina —— 基底层(基板)\n• Figure 9-24 —— 图9-24《分子细胞生物学》\n• 5 μm —— 5 微米(标尺)\n【读图讲解】\n扫描电镜：小肠吸收上皮游离面密集的微绒毛(microvilli)，可见柱状细胞顶面与基膜(basal lamina)。考点：微绒毛由微丝束支撑，增大吸收面积。","page":37,"level":"掌握","img":"assets/img/ch07/p037.jpg","anim":null,"fig":null,"points":["Absorptive","epithelial","Microvilli","cells","Basal","lamina","5μm","Figure9-24"],"check":null,"cards":null},{"i":37,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"Gut epithelium: actin filaments","notes":"【结合课本/笔记】●核纤层(Nuclear Lamina )一、微丝(microfilament, MF)又称肌动蛋白纤维(actin filament), 是指真核细胞中由肌动蛋白(actin)组成、直径为7nm的骨架纤维。●成分●装配●微丝特异性药物●微丝结合蛋白●微丝功能●肌肉收缩(muscle contraction)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页讲解】\n本页展示肠上皮（gut epithelium）微绒毛内肌动蛋白丝（actin filaments）的分布。左侧为电镜纵切面，红色高亮标出微绒毛轴心内平行排列的肌动蛋白丝束，其下端延伸进入细胞顶部的终末网（terminal web）；右侧为微绒毛横切面，各圆形轮廓中央的红色点簇即肌动蛋白丝束的横断面。两图对照说明：一束肌动蛋白丝沿微绒毛长轴排列并向下锚定，为微绒毛提供支持并参与吸收功能。关键术语：微绒毛（microvillus）、肌动蛋白丝（actin filament）、终末网（terminal web）。考点：微绒毛的核心结构是肌动蛋白丝束，是细胞表面特化与细胞骨架功能的经典例证。","page":38,"level":"掌握","img":"assets/img/ch07/p038.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":38,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"小肠上皮细胞微绒毛   内耳耳蜗毛细胞顶端静","notes":"纤毛，即微绒毛横切面。\n\n【读图讲解】\n本图展示小肠上皮细胞微绒毛与内耳静纤毛。A为微绒毛模式图：中央是微丝束，微丝正极朝顶端，束内含有肌球蛋白I及交联蛋白(绒毛蛋白、丝束蛋白、胞衬蛋白)；顶部为无定型的致密染色区，即端网，外包质膜。B为电镜纵切照片，标出微绒毛、微丝束、质膜与端网，标尺100 nm。C为静纤毛(微绒毛)横切面电镜图，呈致密均匀状，即内耳耳蜗毛细胞顶端静纤毛的横切面。要点：微绒毛以微丝束为核心、不能运动，与含9+2微管的纤毛不同。","page":39,"level":"掌握","img":"assets/img/ch07/p039.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":39,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"静纤毛","notes":"The role of actin and myosin VIIa,VI, XV in hearing\nMyosin VIIa is localized in the hair\ncells of the cochlea of the inner ear.\n位于内耳耳蜗的毛细胞中。\nbundle of stiff, hairlike\nstereocilia(静纤毛) that project\nfrom the apical surface of the cell\ninto the inner ear.\nDisplacement(移动，移位) of the\nstereocilia by mechanical stimuli\nleads to the generation of nerve\nimpulses that we perceive as sound.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌动蛋白与肌球蛋白VIIa、VI、XV在听觉(hearing)中的作用。肌球蛋白VIIa(myosin VIIa)定位于内耳耳蜗(cochlea)的毛细胞(hair cells)中。毛细胞因顶端伸入内耳的一束坚硬毛状静纤毛(stereocilia)而得名。机械刺激使静纤毛发生位移(displacement)，进而产生神经冲动，被我们感知为声音。可见静纤毛中的actin与myosin对听力至关重要。对应翟中和第十章微丝在特殊细胞结构中的功能。","page":40,"level":"掌握","img":"assets/img/ch07/p040.jpg","anim":null,"fig":null,"points":["Hair cells are named for the"],"check":{"q":"关于「静纤毛」，下列说法正确的是（　）","o":["A. 细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","B. 单体隔离蛋白(monomer-sequestering-protein):","C. 头部(head domain)","D. Hair cells are named for the"],"a":"D","e":"本页要点：Hair cells are named for the","oe":["收缩环属胞质分裂内容，与静纤毛无关。","单体隔离蛋白属微丝结合蛋白，非静纤毛结构。","头部结构域属肌球蛋白结构，与静纤毛无关。","正确——静纤毛位于内耳毛细胞，可感受听觉的机械刺激。"]},"cards":null},{"i":40,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"听觉毛细胞","notes":"顶盖膜\n支持细胞\n静纤毛\n基膜\n听觉神经\n\n【读图讲解】\n本图为内耳听觉感受器(柯蒂氏器)模式图。基膜(basilar membrane)上坐落支持细胞(supporting cell)和听觉毛细胞(auditory hair cells)，毛细胞顶端伸出静纤毛(stereocilia)并与上方黄色的顶盖膜(tectorial membrane)接触；毛细胞底部连接听觉神经纤维(auditory nerve fibers)。右侧方框放大显示毛细胞顶端：数根静纤毛呈梯度排列在细胞表面。要点：声波引起基膜振动、静纤毛偏转，使毛细胞兴奋，经听觉神经传入中枢；注意静纤毛属微绒毛性质，非真正的纤毛。","page":41,"level":"掌握","img":"assets/img/ch07/p041.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":41,"sec":"2.4. 2 非肌细胞中高度有序排列的微","title":"Mutant of myosin VIIa","notes":"CK\nf. Scanning electron micrograph of the hair cells of a control\nmouse. The stereocilia are arranged in V-shaped rows.\ng. The hair cells of a mouse with mutations in the gene encoding\nmyosin VIIa, which causes deafness. The stereocilia of the\nhair cells exhibit a disorganized arrangement.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.1 肌肉收缩 ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌球蛋白VIIa(myosin VIIa)的突变体。原文给出对照(CK)与突变小鼠毛细胞的扫描电镜图：对照小鼠的静纤毛(stereocilia)排列成V形行(V-shaped rows)；而编码myosin VIIa的基因发生突变的小鼠(可引起耳聋)其毛细胞静纤毛排列紊乱(disorganized arrangement)。这说明肌球蛋白VIIa对维持静纤毛的有序排列是必需的。对应翟中和第十章微丝与肌球蛋白在听觉毛细胞中的作用。","page":42,"level":"掌握","img":"assets/img/ch07/p042.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_mcq_1","mod":"2.4.1 肌肉收缩","modI":8,"q":"具有破坏微丝结构的特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"B","e":"细胞松弛素（cytochalasins）是真菌的一种代谢产物，可以切断微丝，并可结合在 微丝末端阻抑肌动蛋白聚合。","kp":"ch07_s8_37","oe":["秋水仙素破坏微管，不是破坏微丝的药物的。","正确——细胞松弛素是真菌代谢产物，切断微丝并抑制肌动蛋白聚合。","鬼笔环肽稳定微丝、抑制其解聚，并不破坏微丝。","紫杉酚稳定微管、抑制其解聚，作用于微管。"]},{"id":"ch07_mcq_6","mod":"2.4.1 肌肉收缩","modI":8,"q":"在只有肌动蛋白而无肌球蛋白的情况下，下列哪种形式的细胞运动可以发生？（                   ）","o":["A．骨骼肌收缩","B．胞质分裂","C．卵细胞受精前的顶体反应","D．胞质环流","E．上述细胞运动都不能发生"],"a":"E","e":"肌动蛋白是微丝的组成单元，而肌球蛋白是微丝的马达蛋白。ABCD 四项所述运动 形式均与微丝有关。","kp":"ch07_s8_32","oe":["骨骼肌收缩需肌动蛋白与肌球蛋白相互作用才能发生。","胞质分裂需肌动蛋白与肌球蛋白II形成收缩环。","顶体反应依赖肌动蛋白与肌球蛋白协同，缺肌球蛋白不能完成。","胞质环流依赖肌动蛋白与肌球蛋白的相互作用。","正确——上述运动均需肌动蛋白与肌球蛋白协同，故都不能发生。"]}],"judge":[{"id":"ch07_judge_2","modI":8,"q":"微丝由α-微管蛋白和β-微管蛋白两种微管蛋白亚基形成，微管的主要结构成分是肌动蛋 白（actin）。（     ）","a":"错","e":"微管由α-微管蛋白和β-微管蛋白两种微管蛋白亚基形成，微丝的主要结构成分是肌 动蛋白（actin）。","kp":"ch07_s8_37"}],"fill":[{"id":"ch07_fill_5","modI":8,"q":"微丝是指真核细胞中由________组成，直径为________的骨架纤维。","a":"肌动蛋白；7 nm","kp":"ch07_s8_37"}],"short":[],"calc":[],"term":[]},{"i":9,"name":"第二节 微丝 · 2.4.3 应力纤维(Stress fi","slides":[{"i":42,"sec":"2.4.3 应力纤维(Stress fi","title":"体外培养的星状胶质细胞","notes":"中的应力纤维\n2.4.3 应力纤维(Stress fiber)\n应力纤维；沿细胞的长轴排列，并与质膜的黏着斑连接。\n应力纤维在细胞形态建成、细胞运动等过程中有重要作\n用。","page":43,"level":"掌握","img":"assets/img/ch07/p043.jpg","anim":null,"fig":null,"points":["动物成纤维细胞中微丝可以形成粗大的微丝束，即"],"check":{"q":"关于「体外培养的星状胶质细胞」，下列说法正确的是（　）","o":["A. An initial group of several subunits to associate correctly, to","B. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","C. 动物成纤维细胞中微丝可以形成粗大的微丝束，即","D. 微丝是由G-actin单体形成的多聚体"],"a":"C","e":"本页要点：动物成纤维细胞中微丝可以形成粗大的微丝束，即","oe":["该英文指微丝聚合起始，与星状胶质细胞无关。","肌原纤维属骨骼肌收缩结构，非星状胶质细胞。","正确——培养细胞中微丝可形成应力纤维，与细胞贴附运动有关。","微丝由G-actin聚合属微丝基本结构，非本题要点。"]},"cards":null},{"i":43,"sec":"2.4.3 应力纤维(Stress fi","title":"含actin, myosin, Tm,","notes":"filamin, α-actinin等成分\n培养的成纤维细胞中具有丰\n富的应力纤维，并通过粘\n着斑固定在基质上。\n与细胞间/细胞与基质表\n面的粘着有关。","page":44,"level":"掌握","img":"assets/img/ch07/p044.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":44,"sec":"2.4.3 应力纤维(Stress fi","title":"正常态                Platelets change shape during","notes":"blood clotting 血小板在凝血过程\n中的形态变化。\nResting cells                    When exposed to\nclotting agents, the cells\nsettle on the substratum,\nextend numerous\nfilopodia.\nThe changes in morphology\nresult from complex\nrearrangements of the actin\ncytoskeleton, which is cross-\nlinked to the plasma membrane.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.3 应力纤维(Stress fi ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页主题是血小板(platelets)在凝血(blood clotting)过程中的形态变化。静止态(resting cells)的血小板在接触凝血因子(clotting agents)后，会贴附于基质(substratum)并伸出许多丝状伪足(filopodia)。原文指出，这种形态改变源于肌动蛋白细胞骨架(actin cytoskeleton)的复杂重排，而该骨架与质膜(plasma membrane)交联。对应翟中和第十章微丝参与细胞形态改变与运动，是微丝在非肌细胞中功能的实例。","page":45,"level":"掌握","img":"assets/img/ch07/p045.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[],"fill":[{"id":"ch07_fill_4","modI":9,"q":"肌球蛋白Ⅱ在细胞中的功能有两个方面：参与_________和_________。","a":"胞质分裂；肌收缩","kp":"ch07_s9_42"}],"short":[{"id":"ch07_short_4","modI":9,"q":"何谓细胞骨架？微管、微丝在细胞骨架中的主要作用是什么？","a":"细胞骨架是细胞内以蛋白质纤维为主要成分的网络结构，由微管、微丝、中间纤维组成。 微管功能大致分为四个方面：支架作用，维持细胞形态、定位细胞器；作为胞内物质运输的 轨道；作为纤毛、鞭毛的运动元件；参与细胞分裂。微丝的功能包括：肌细胞中参与肌原纤 维收缩；在非肌细胞中参与胞质分裂、胞质环流、吞噬作用、细胞变形运动、膜泡运输、细 胞黏着与连接等。中间纤维为细胞提供机械强度支持；参与细胞连接（桥粒与半桥粒）；维 持核膜稳定；结蛋白（desmin）及相关蛋白对肌节的稳定作用。","kp":"ch07_s9_42"}],"calc":[],"term":[{"id":"ch07_term_4","modI":9,"term":"应力纤维（stress fiber）。","def":"真核细胞胞质内由微丝平行排列构成的微丝束称为应力纤维。它参与黏合斑的形成和细 胞的移动。在细胞的形态发生、细胞分化和组织形成中，应力纤维具有重要的作用。","kps":"","kp":"ch07_s9_42"}]},{"i":10,"name":"第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell","slides":[{"i":45,"sec":"2.4.4 细胞爬行运动(cell cr","title":"2.4.4 细胞爬行运动(cell crawling, cell","notes":"locomotion)、变形运动(amoeboid movement)\n胞、白细胞等没有鞭毛、纤毛等运动器官，依\n靠细胞型体的变化进行移动，为变形运动。\n(如伤口愈合，防止感染、血块凝集等)\nCell crawling depends on actin.\n伪足(lamellipodia)－主要由actin聚合形成。","page":46,"level":"掌握","img":"assets/img/ch07/p046.jpg","anim":null,"fig":null,"points":["原生动物中的变形虫，高等动物中的巨噬细","首先细胞前缘扩展，形成伪足(pseudopodia)/片层"],"check":{"q":"关于「细胞爬行运动(cell crawling, ce…」，下列说法正确的是（　）","o":["A. 微丝是由G-actin单体形成的多聚体","B. 原生动物中的变形虫，高等动物中的巨噬细","C. Myosin I 重链无α-螺旋序","D. 细胞信号转导"],"a":"B","e":"本页要点：原生动物中的变形虫，高等动物中的巨噬细","oe":["微丝由G-actin聚合属微丝基本结构，非爬行运动。","正确——变形虫、巨噬细胞和成纤维细胞均以微丝进行爬行运动。","Myosin I结构属肌球蛋白类型，非细胞爬行运动。","细胞信号转导属微丝功能之一，非细胞爬行运动。"]},"cards":null},{"i":46,"sec":"2.4.4 细胞爬行运动(cell cr","title":"A neutrophil in pursuit of bacteria.","notes":"【结合课本/笔记】原核细胞基本特点：●遗传的信息量小，遗传信息载体仅由一个环状DNA构成；细胞内没有分化为以膜为基础的具有专门结构与功能的细胞器和细胞核膜。主要代表：●支原体（mycoplast）——目前发现的最小最简单的细胞；●细菌●蓝藻又称蓝细菌（Cyanobacteria）\n\n【本页英文讲解】\n本页主题是一个中性粒细胞(neutrophil)追逐细菌(A neutrophil in pursuit of bacteria)的过程。原文仅给出这一标题，画面展示中性粒细胞向细菌方向迁移。这类运动依赖肌动蛋白细胞骨架在细胞前缘的组装与后部解聚，使细胞产生定向移动。可联系翟中和第十章微丝驱动的细胞迁移。原文文字残缺，故只解释能看懂的主题与术语。","page":47,"level":"掌握","img":"assets/img/ch07/p047.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":47,"sec":"2.4.4 细胞爬行运动(cell cr","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Macrophage —— 巨噬细胞\n• Bacteria (Staphylococcus) —— 细菌(葡萄球菌)\n• Filopodium engulfing bacteria —— 丝状伪足正在吞噬细菌\n• Figure 6.31 The emergence of cellular functions —— 图6.31 细胞功能的涌现\n• 10 µm —— 10 微米(标尺)\n• cytoskeleton, lysosomes, plasma membrane in phagocytosis —— 细胞骨架、溶酶体、质膜共同参与吞噬作用\n【读图讲解】\n彩色SEM：巨噬细胞(macrophage)伸出丝状伪足(filopodium)捕捉并吞噬金黄色葡萄球菌(bacteria)。考点：吞噬作用是细胞骨架、质膜与溶酶体协同的整体活动。","page":48,"level":"掌握","img":"assets/img/ch07/p048.jpg","anim":null,"fig":null,"points":["functioninphagocytosis(colorizedSEM).","Macrophage","Bacteria","Filopodium(extension","ofthemacrophage)","engulfingbacteria","10μm"],"check":null,"cards":null},{"i":48,"sec":"2.4.4 细胞爬行运动(cell cr","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• tail —— 尾部\n• leading edge —— 前缘(引导缘)\n• lamellipodium —— 片状伪足\n• ruffled membrane —— 皱褶膜\n• Figure 9.68 mouse fibroblast crawling —— 图9.68 小鼠成纤维细胞爬行\n• Figure 9.70 leading edge of a motile cell —— 图9.70 运动细胞的前缘\n• 15 µm —— 15 微米(标尺)\n【读图讲解】\n左：小鼠成纤维细胞爬行SEM，示尾部(tail)与前缘(leading edge，扁平片状伪足 lamellipodium)；右：运动细胞前缘贴附基质铺成面纱状片状伪足。考点：细胞迁移时前缘片状伪足的形成与铺展。","page":49,"level":"掌握","img":"assets/img/ch07/p049.jpg","anim":null,"fig":null,"points":["tail","leading","edge","15μm","BUEHLER,INT.REV.CYTOL.120:194,1990.)","(D)"],"check":null,"cards":null},{"i":49,"sec":"2.4.4 细胞爬行运动(cell cr","title":"⎯首先细胞前缘扩展，形成伪足(pseudopodia)/","notes":"片层伪足(lamellipodia):\n丝状伪足和片状伪足都是探索性、可移动的结\n构，其形成和回缩的速度极快，移动的速度约\n为1μm/sec\n主要由actin聚合，快速生长而形成。\n(Actin polymerization drives plasma membrane\nprotrusion.)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异","page":50,"level":"掌握","img":"assets/img/ch07/p050.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":50,"sec":"2.4.4 细胞爬行运动(cell cr","title":"⎯As the bacteria move, the neutrophil","notes":"quickly reassembles the dense actin network\nat the leading edge (red) to push toward the\nlocation of the bacteria.\nthe actin cytoskeleton in this cell enables it to\nchange its orientation and direction of\nmovement within a few seconds.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页继续讲中性粒细胞(neutrophil)追踪细菌的机制。原文指出：随着细菌移动，中性粒细胞会迅速在前缘(leading edge，红色)重新组装致密的肌动蛋白网络(actin network)，以推动细胞朝细菌所在位置前进。这种肌动蛋白细胞骨架的快速解聚(disassembly)与再组装(reassembly)，使细胞能在几秒内改变取向和运动方向。对应翟中和第十章微丝动态组装驱动细胞迁移，是微丝功能的重要考点。","page":51,"level":"掌握","img":"assets/img/ch07/p051.jpg","anim":null,"fig":null,"points":["Rapid disassembly and reassembly of"],"check":{"q":"关于「⎯As the bacteria move, t…」，下列说法正确的是（　）","o":["A. 直径7nm 组成蛋白：球形肌动蛋白(G-actin)","B. 真菌的一种代谢产物(metabolite of fungal)","C. Rapid disassembly and reassembly of","D. 肠上皮细胞(intestinal epithelial cells)表面细胞膜向"],"a":"C","e":"本页要点：Rapid disassembly and reassembly of","oe":["7nm与G-actin属微丝结构，与细菌运动无关。","真菌代谢产物指细胞松弛素，属微丝药物。","正确——微丝快速解聚与重组装可驱动细胞运动。","肠上皮细胞微绒毛微丝束属微丝束，非本题要点。"]},"cards":null},{"i":51,"sec":"2.4.4 细胞爬行运动(cell cr","title":"培养皿中的鱼角膜细胞","notes":"The roles of actin and myosin in the\nlamellipodial-based movement of fish keratocytes\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页主题是肌动蛋白和肌球蛋白在鱼角膜细胞(fish keratocytes)基于片状伪足(lamellipodial)的运动中的作用。原文标题为“The roles of actin and myosin in the lamellipodial-based movement of fish keratocytes”，并配以“培养皿中的鱼角膜细胞”说明。鱼角膜细胞是研究细胞迁移的经典模型，其前缘片状伪足富含微丝。对应翟中和第十章微丝参与细胞运动，可作为理解细胞迁移机制的实例。","page":52,"level":"掌握","img":"assets/img/ch07/p052.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":52,"sec":"2.4.4 细胞爬行运动(cell cr","title":"2. these protrusions","notes":"adhere to the\nsubstratum by focal\nadhensions\nActin filaments allow animal cells to migrate\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是动物细胞迁移中凸起与黏附的作用。原文指出：这些凸起(protrusions，如片状伪足、丝状伪足)通过黏着斑(focal adhesions)黏附到基质(substratum)上；肌动蛋白丝(actin filaments)使动物细胞得以迁移(migrate)。可见细胞迁移大致包括前缘凸起、黏附、收缩与后部解离等步骤。对应翟中和第十章微丝驱动的细胞迁移，黏着斑是微丝与胞外基质联系的重要结构，常考。","page":53,"level":"掌握","img":"assets/img/ch07/p053.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":53,"sec":"2.4.4 细胞爬行运动(cell cr","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• actin —— 肌动蛋白\n• myosin —— 肌球蛋白\n• integrins —— 整合素\n• extracellular matrix —— 细胞外基质\n• retrograde flow —— 逆行流动\n• protrusion —— 突出(前突)\n• traction —— 牵引力\n• (A) assembly —— (A) 肌动蛋白单体在前缘倒刺端(正端)组装\n• (B) DISENGAGED —— (B) 未连接：丝与黏着斑无作用，被新组装肌动蛋白向后推\n• (C) ENGAGED —— (C) 已连接：整合素-衔接蛋白连接骨架，肌球蛋白收缩产生牵引力、推动前缘前伸\n• Figure 16-82 —— 图16-82 迁移细胞前缘黏附的调控\n【读图讲解】\n示意图示迁移细胞前缘黏着调控三态(初始/未结合/结合)：肌动蛋白在倒刺端聚合、整合素形成黏着斑、肌球蛋白收缩传递牵引力并推动前缘前伸。考点：整合素黏着与肌动蛋白逆行流(treadmilling)。","page":54,"level":"掌握","img":"assets/img/ch07/p054.jpg","anim":null,"fig":null,"points":["(A)","Figure16-82Controlofcell-","substratumadhesionattheleading","actin","edgeofamigratingcell.(A)Actin","monomersassembleonthebarbedend","of actinfilaments at theleading edge.","Transmembrane integrinproteins (blue)"],"check":null,"cards":null},{"i":54,"sec":"2.4.4 细胞爬行运动(cell cr","title":"细胞的变形运动(all these processes involve actin","notes":"in different ways)\n①微丝纤维生长，使细胞表面突出，形成片足\n(lamellipodium)；\n②在片足与基质接触的位置形成粘着斑(focal adhesions)\n(integrin-MFs)，附着在基质(substratum)上；\n③在myosin的作用下微丝纤维滑动，使细胞主体前移；\n④解除细胞后方尾部的粘和点。\n如此不断循环，细胞向前移动。\n阿米巴原虫、白细胞、成纤维细胞都能以这种方\n式运动。","page":55,"level":"掌握","img":"assets/img/ch07/p055.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":55,"sec":"2.4.4 细胞爬行运动(cell cr","title":"Localization of actin","notes":"in a wounded\nmonolayer 5\nminutes and 3 hours\nafter scratching;\nthe cells have\nmigrated into the\nwounded area.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异\n\n【本页英文讲解】\n本页主题是划痕实验中肌动蛋白(actin)的定位。原文描述：在单层细胞(monolayer)上划痕后5分钟和3小时，观察肌动蛋白的分布，可见细胞已迁移进划伤区域(wounded area)。该实验利用微丝在迁移细胞前缘的富集来研究细胞运动与创伤修复。对应翟中和第十章微丝参与细胞迁移的功能，是常用的细胞运动实验模型。","page":56,"level":"掌握","img":"assets/img/ch07/p056.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_8","mod":"第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell","modI":10,"q":"关于「细胞爬行运动(cell crawling, ce」，下列说法正确的是（　）","o":["A. 原生动物中的变形虫，高等动物中的巨噬细","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"A","e":"本页要点：原生动物中的变形虫，高等动物中的巨噬细","kp":"ch07_s10_45","oe":["正确——变形虫、巨噬细胞和成纤维细胞靠微丝进行细胞爬行。","微丝7nm与G-actin属微丝结构，非细胞爬行运动。","微丝由G-actin聚合属微丝基本结构，非细胞爬行运动。","微丝动态装配属微丝动态性，非细胞爬行运动。"]}],"judge":[{"id":"ch07_ajudge_9","modI":10,"q":"原生动物中的变形虫，高等动物中的巨噬细","a":"对","e":"本页要点：原生动物中的变形虫，高等动物中的巨噬细","kp":"ch07_s10_45"}],"fill":[],"short":[{"id":"ch07_short_1","modI":10,"q":"简述微丝的结构特点。","a":"肌动蛋白（actin）是微丝的结构成分，以单体和多聚体两种形式存在。单体肌动蛋白又 称球状肌动蛋白（G-actin），G-actin 的多聚体形成肌动蛋白丝，称为纤维状肌动蛋白（F-actin）， 在电镜下微丝是一条直径为 7nm 的扭链，呈双股螺旋状。肌动蛋白单体具有极性，装配时 呈头尾相接，故微丝也具有极性，即正极与负极之别。","kp":"ch07_s10_49"}],"calc":[],"term":[]},{"i":11,"name":"第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring)","slides":[{"i":56,"sec":"2.4.5 胞质分裂的收缩环(contr","title":"2.4.5 胞质分裂的收缩环(contractile ring)","notes":"互作用将细胞分开，最终完成细胞的胞质分裂\nFluorescence image of a Dictyostelium ameba during\ncytokinesis reveals that myosin II is in the cleavage\nfurrow.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环（contractile ring）：有丝分裂末期，胞质分裂开始时，大量肌动蛋白和肌球蛋白在细胞膜下聚集形成收缩环。\n• 分裂沟（cleavage furrow）：收缩环通过微丝滑动、直径逐渐变小、使细胞膜凹陷，产生与纺锤体轴相垂直的分裂沟。\n\n【本页英文讲解】\n本页主题是胞质分裂的收缩环(contractile ring)。细胞分裂中，微丝与肌球蛋白II(myosin II)形成收缩环，二者相互作用将细胞缢缩分开，最终完成胞质分裂(cytokinesis)。原文还以盘基网柄菌(Dictyostelium ameba)的荧光图像说明，肌球蛋白II定位在分裂沟(cleavage furrow)处。对应翟中和第十章微丝与肌球蛋白参与胞质分裂，是微丝功能的经典考点。","page":57,"level":"掌握","img":"assets/img/ch07/p057.jpg","anim":null,"fig":null,"points":["细胞分裂中微丝和肌球蛋白 II 形成收缩环，相"],"check":{"q":"关于「胞质分裂的收缩环(contractile rin…」，下列说法正确的是（　）","o":["A. 细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","B. An initial group of several subunits to associate correctly, to","C. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","D. 微丝是由G-actin单体形成的多聚体"],"a":"A","e":"本页要点：细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","oe":["正确——胞质分裂时微丝与肌球蛋白II构成收缩环，使细胞缢缩。","该英文指微丝聚合起始，与收缩环无关。","肌原纤维属骨骼肌收缩结构，非胞质分裂收缩环。","微丝由G-actin聚合属微丝基本结构，非收缩环。"]},"cards":null},{"i":57,"sec":"2.4.5 胞质分裂的收缩环(contr","title":"A fly spermatocyte(精母细","notes":"A cultured animal\ncell in the process\nof diving\n胞)undergoing cytokinesis.\nF-actin are seen to be\nconcentrated in a circular\nequatorial band within the\ncleavage furrow.(2004)\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环（contractile ring）：有丝分裂末期，胞质分裂开始时，大量肌动蛋白和肌球蛋白在细胞膜下聚集形成收缩环。\n• 分裂沟（cleavage furrow）：收缩环通过微丝滑动、直径逐渐变小、使细胞膜凹陷，产生与纺锤体轴相垂直的分裂沟。\n\n【本页英文讲解】\n本页主题是正在胞质分裂(cytokinesis)的细胞，以果蝇精母细胞(fly spermatocyte)为例。原文指出，可见F-actin浓集于分裂沟(cleavage furrow)内一个环形的赤道带(circular equatorial band)中。这正是收缩环(contractile ring)的直观证据，说明微丝在细胞赤道部组装成环，通过收缩把细胞一分为二。对应翟中和第十章微丝与肌球蛋白II构成收缩环完成胞质分裂。原文标注2004年。","page":58,"level":"掌握","img":"assets/img/ch07/p058.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":58,"sec":"2.4.5 胞质分裂的收缩环(contr","title":"F-actin(red) are located at","notes":"both the cleavage furrow and\nthe cell periphery where they\nplay a key role in cell\nmovement.\nMyosin II (green) is localized\nat the cleavage furrow.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环（contractile ring）：有丝分裂末期，胞质分裂开始时，大量肌动蛋白和肌球蛋白在细胞膜下聚集形成收缩环。\n• 分裂沟（cleavage furrow）：收缩环通过微丝滑动、直径逐渐变小、使细胞膜凹陷，产生与纺锤体轴相垂直的分裂沟。\n\n【本页英文讲解】\n本页主题是胞质分裂中F-actin与肌球蛋白II(myosin II)的定位。原文指出：F-actin(红色)分布于分裂沟(cleavage furrow)和细胞周边(cell periphery)两处，前者参与分裂，后者在细胞运动中起关键作用；而肌球蛋白II(绿色)只定位于分裂沟处。这说明收缩环由微丝与肌球蛋白II共同组成。对应翟中和第十章胞质分裂收缩环的组成，是荧光定位证据类考点。","page":59,"level":"掌握","img":"assets/img/ch07/p059.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":59,"sec":"2.4.5 胞质分裂的收缩环(contr","title":"Treated:","notes":"●delete myosin II\ngene\n●inject anti-myosin\nII antibodies\nInhibition of myosin II demonstrates that it is\nrequired for cytokinesis.\n【中文讲解·对照课本/考点】\n考点：第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring) ｜ 教材：第十章 细胞骨架 · 第一节 微丝与细胞运动（教材 p194–205）\n• 收缩环（contractile ring）：有丝分裂末期，胞质分裂开始时，大量肌动蛋白和肌球蛋白在细胞膜下聚集形成收缩环。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页给出肌球蛋白II(myosin II)参与胞质分裂的抑制实验证据。处理方法(Treated)包括：去除/敲除肌球蛋白II基因(delete myosin II gene)、注射抗肌球蛋白II抗体(inject anti-myosin II antibodies)。原文结论是：抑制肌球蛋白II可证明它是胞质分裂所必需的(Inhibition of myosin II demonstrates that it is required for cytokinesis)。对应翟中和第十章收缩环中肌球蛋白II的功能，是典型的实验论证考点。","page":60,"level":"掌握","img":"assets/img/ch07/p060.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch07_amcq_10","mod":"第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring)","modI":11,"q":"关于「胞质分裂的收缩环(contractile rin」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. 微丝是由G-actin单体形成的多聚体","C. 细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"C","e":"本页要点：细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","kp":"ch07_s11_56","oe":["微丝7nm与G-actin属微丝结构，非胞质分裂收缩环。","微丝由G-actin聚合属微丝基本结构，非收缩环。","正确——胞质分裂时微丝与肌球蛋白II构成收缩环，使细胞缢裂。","微丝动态装配属微丝动态性，非胞质分裂收缩环。"]}],"judge":[{"id":"ch07_ajudge_11","modI":11,"q":"细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","a":"对","e":"本页要点：细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","kp":"ch07_s11_56"}],"fill":[],"short":[],"calc":[],"term":[]}],"mcq":[{"id":"ch07_mcq_1","mod":"2.4.1 肌肉收缩","modI":8,"q":"具有破坏微丝结构的特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"B","e":"细胞松弛素（cytochalasins）是真菌的一种代谢产物，可以切断微丝，并可结合在 微丝末端阻抑肌动蛋白聚合。","kp":"ch07_s8_37","oe":["秋水仙素破坏微管，不是破坏微丝的药物的。","正确——细胞松弛素是真菌代谢产物，切断微丝并抑制肌动蛋白聚合。","鬼笔环肽稳定微丝、抑制其解聚，并不破坏微丝。","紫杉酚稳定微管、抑制其解聚，作用于微管。"]},{"id":"ch07_mcq_2","mod":"2.3 微丝特异性药物(Specific drug for MF)","modI":3,"q":"用特异性药物细胞松弛素 B 可以阻断下列哪种小泡的形成？（        ）","o":["A．胞饮泡","B．吞噬泡","C．分泌小泡","D．包被小泡"],"a":"B","e":"吞噬泡的形成与细胞膜下富含肌动蛋白纤维的溶胶区域的状态转化有关，能为细胞 松弛素所抑制。","kp":"ch07_s3_21","oe":["胞饮泡形成与网格蛋白及膜内陷相关，不被细胞松弛素B阻断。","正确——吞噬泡形成依赖膜下肌动蛋白，可被细胞松弛素B抑制。","分泌小泡由高尔基体出芽形成，与微丝无关。","包被小泡由网格蛋白或COP包被形成，与微丝无关。"]},{"id":"ch07_mcq_3","mod":"2.4 微丝的功能","modI":4,"q":"构成微丝的基本成分是（         ）。","o":["A．肌动蛋白","B．肌球蛋白","C．肌钙蛋白","D．三者均有"],"a":"A","e":"微丝（microfilament，MF）的主要结构成分是肌动蛋白。B 项，肌球蛋白是依赖于 微丝的分子马达；C 项，肌钙蛋白是结合在横纹肌细肌丝上的调节蛋白，有三个亚基组成： 肌钙蛋白 T、肌钙蛋白 I 和肌钙蛋白 C。其中肌钙蛋白 T 能与原肌球蛋白结合，肌钙蛋白 I 能抑制肌球蛋白的 ATPase 活性，肌钙蛋白 C 能与钙离子结合。","kp":"ch07_s4_22","oe":["正确——微丝的主要结构成分是肌动蛋白。","肌球蛋白是依赖微丝的马达蛋白，不是微丝的组成成分。","肌钙蛋白是横纹肌细肌丝上的调节蛋白，非微丝基本成分。","三者并非都是微丝成分，微丝基本成分只有肌动蛋白。"]},{"id":"ch07_mcq_4","mod":"2.2 微丝结合蛋白","modI":2,"q":"关于肌动蛋白的叙述错误的是（         ）。","o":["A．G-肌动蛋白与 F-肌动蛋白可互相转变","B．肌动蛋白上有肌球蛋白结合位点，但无二价阳离子的结合位点","C．F______肌动蛋白的聚合过程不需能量","D．肌动蛋白是微丝的基础蛋白质"],"a":"B","e":"B 选项肌动蛋白有 ATP 结合位点和 Mg2 结合位点。 ＋","kp":"ch07_s2_18","oe":["G-肌动蛋白与F-肌动蛋白可互相转变，此叙述正确，故不选。","正确——肌动蛋白有ATP及Mg2+结合位点，说其无二价阳离子位点错误。","F-肌动蛋白的聚合需ATP供能，该叙述正确，故不选。","肌动蛋白是微丝的基础蛋白质，此叙述正确，故不选。"]},{"id":"ch07_mcq_5","mod":"2.2 微丝结合蛋白","modI":2,"q":"下列物质中，能抑制微丝解聚的是（           ）。","o":["A．秋水仙素","B．紫杉醇","C．鬼笔环肽","D．细胞松弛素 B"],"a":"C","e":"A 项，秋水仙素能抑制微管的组装，而不影响其解聚。B 项，紫衫醇能抑制微管的 解聚，而不影响其组装。D 项，细胞松弛素 B 能抑制微丝的组装，而不影响其解聚。","kp":"ch07_s2_10","oe":["秋水仙素抑制微管的组装，不影响微丝的解聚。","紫杉醇抑制微管的解聚，作用于微管而非微丝。","正确——鬼笔环肽与F-actin结合，稳定微丝并抑制其解聚。","细胞松弛素B抑制微丝的组装，而非抑制微丝解聚。"]},{"id":"ch07_mcq_6","mod":"2.4.1 肌肉收缩","modI":8,"q":"在只有肌动蛋白而无肌球蛋白的情况下，下列哪种形式的细胞运动可以发生？（                   ）","o":["A．骨骼肌收缩","B．胞质分裂","C．卵细胞受精前的顶体反应","D．胞质环流","E．上述细胞运动都不能发生"],"a":"E","e":"肌动蛋白是微丝的组成单元，而肌球蛋白是微丝的马达蛋白。ABCD 四项所述运动 形式均与微丝有关。","kp":"ch07_s8_32","oe":["骨骼肌收缩需肌动蛋白与肌球蛋白相互作用才能发生。","胞质分裂需肌动蛋白与肌球蛋白II形成收缩环。","顶体反应依赖肌动蛋白与肌球蛋白协同，缺肌球蛋白不能完成。","胞质环流依赖肌动蛋白与肌球蛋白的相互作用。","正确——上述运动均需肌动蛋白与肌球蛋白协同，故都不能发生。"]},{"id":"ch07_amcq_1","mod":"第二节 微丝 · 二、 微丝(Microfilament, MF)","modI":0,"q":"关于「微丝(Microfilament, MF)」，下列说法正确的是（　）","o":["A. 微丝是由G-actin单体形成的多聚体","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，","D. actin单体具极性, 装配时头尾相接α微丝(F-actin)也具极性;"],"a":"B","e":"本页要点：直径7nm                组成蛋白：球形肌动蛋白(G-actin)","kp":"ch07_s0_0","oe":["微丝确由G-actin聚合形成，但题干考的是直径与组成蛋白","微丝直径约7nm，由球形肌动蛋白G-actin组成，正确","该说法正确，但描述微丝动态性，非直径与组成蛋白","该说法正确，但描述微丝极性，非直径与组成蛋白要点"]},{"id":"ch07_amcq_4","mod":"第二节 微丝 · 2.4.2 sliding of myo","modI":6,"q":"关于「sliding of myo」，下列说法正确的是（　）","o":["A. 心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"A","e":"本页要点：心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","kp":"ch07_s6_24","oe":["正确——平滑肌肌球蛋白沿微丝滑动，产生心脏搏动与胃肠蠕动。","微丝7nm与G-actin属微丝结构，非肌球蛋白滑动。","微丝由G-actin聚合属微丝基本结构，非肌球蛋白滑动。","微丝动态装配属微丝的动态性，非肌球蛋白滑动。"]},{"id":"ch07_amcq_6","mod":"第二节 微丝 · 2.4.2 肌肉收缩","modI":7,"q":"关于「肌肉收缩」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. 微丝是由G-actin单体形成的多聚体","C. 骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"C","e":"本页要点：骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","kp":"ch07_s7_27","oe":["微丝7nm与G-actin属微丝结构，非肌肉收缩单位。","微丝由G-actin聚合属微丝基本结构，非肌肉收缩单位。","正确——骨骼肌细胞的收缩单位是肌原纤维，由粗、细肌丝组成。","微丝动态装配属微丝的动态性，非肌肉收缩单位。"]},{"id":"ch07_amcq_8","mod":"第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell","modI":10,"q":"关于「细胞爬行运动(cell crawling, ce」，下列说法正确的是（　）","o":["A. 原生动物中的变形虫，高等动物中的巨噬细","B. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"A","e":"本页要点：原生动物中的变形虫，高等动物中的巨噬细","kp":"ch07_s10_45","oe":["正确——变形虫、巨噬细胞和成纤维细胞靠微丝进行细胞爬行。","微丝7nm与G-actin属微丝结构，非细胞爬行运动。","微丝由G-actin聚合属微丝基本结构，非细胞爬行运动。","微丝动态装配属微丝动态性，非细胞爬行运动。"]},{"id":"ch07_amcq_10","mod":"第二节 微丝 · 2.4.5 胞质分裂的收缩环(contractile ring)","modI":11,"q":"关于「胞质分裂的收缩环(contractile rin」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. 微丝是由G-actin单体形成的多聚体","C. 细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"C","e":"本页要点：细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","kp":"ch07_s11_56","oe":["微丝7nm与G-actin属微丝结构，非胞质分裂收缩环。","微丝由G-actin聚合属微丝基本结构，非收缩环。","正确——胞质分裂时微丝与肌球蛋白II构成收缩环，使细胞缢裂。","微丝动态装配属微丝动态性，非胞质分裂收缩环。"]},{"id":"ch07_amcq_1","mod":"第二节 微丝 · 2.4.1 胞质环流","modI":5,"q":"关于「胞质环流」，下列说法正确的是（　）","o":["A. 直径7nm                组成蛋白：球形肌动蛋白(G-actin)","B. Cytoplasmic streaming in cylindrical giant algae.","C. 微丝是由G-actin单体形成的多聚体","D. 多数非肌细胞中, 微丝是一种动态结构, 持续进行装配/解聚，"],"a":"B","e":"本页要点：Cytoplasmic streaming in cylindrical giant algae.","kp":"ch07_s5_23","oe":["描述微丝直径与组成，与胞质环流现象无关，故不选","胞质环流见于筒状巨藻，由肌动蛋白微丝驱动，正确","描述微丝组成，未说明胞质环流，故不选","描述微丝动态装配，与胞质环流无直接关系，故不选"]}],"judge":[{"id":"ch07_judge_1","modI":1,"q":"细胞中所有的微丝均为动态结构。（          ）","a":"错","e":"体内有些微丝并不是动态的结构，而是永久性的结构，如肌肉中的细丝及肠上皮细 胞微绒毛中的轴心微丝。","kp":"ch07_s1_2"},{"id":"ch07_judge_2","modI":8,"q":"微丝由α-微管蛋白和β-微管蛋白两种微管蛋白亚基形成，微管的主要结构成分是肌动蛋 白（actin）。（     ）","a":"错","e":"微管由α-微管蛋白和β-微管蛋白两种微管蛋白亚基形成，微丝的主要结构成分是肌 动蛋白（actin）。","kp":"ch07_s8_37"},{"id":"ch07_judge_3","modI":7,"q":"α、β、和γ三种类型的肌动蛋白都存在于肌细胞中。（                  ）","a":"错","e":"只有α-肌动蛋白存在于肌细胞中。","kp":"ch07_s7_27"},{"id":"ch07_judge_4","modI":3,"q":"细胞松弛素 B 是真菌的一种代谢产物，可阻止肌动蛋白的聚合，结合到微丝的正极，阻 止新的单体聚合，致使微丝解聚。（                     ）","a":"错","e":"细胞松弛素 B 是一种真菌的代谢产物，与微丝结合后可以将微丝切断，并结合在 微丝末端阻抑肌动蛋白在该部位的聚合，但对微丝的解聚没有明显影响，因而用细胞松弛素 B 处理细胞可以破坏微丝的网络结构，并阻止细胞的运动。","kp":"ch07_s3_21"},{"id":"ch07_judge_5","modI":4,"q":"秋水仙碱可同微丝的（＋）端结合，并阻止新的单体加入。（                         ）","a":"错","e":"秋水仙碱能与微管蛋白亚基结合，具有抑制微管组装的作用。细胞松弛素和鬼笔环 肽是影响微丝组装的特异性药物。","kp":"ch07_s4_22"},{"id":"ch07_ajudge_2","modI":0,"q":"直径7nm                组成蛋白：球形肌动蛋白(G-actin)","a":"对","e":"本页要点：直径7nm                组成蛋白：球形肌动蛋白(G-actin)","kp":"ch07_s0_0"},{"id":"ch07_ajudge_3","modI":4,"q":"细胞信号转导","a":"对","e":"本页要点：细胞信号转导","kp":"ch07_s4_22"},{"id":"ch07_ajudge_5","modI":6,"q":"心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","a":"对","e":"本页要点：心脏的跳动和胃、肠、子宫和动脉的缓慢持久蠕动则依赖","kp":"ch07_s6_24"},{"id":"ch07_ajudge_7","modI":7,"q":"骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","a":"对","e":"本页要点：骨骼肌细胞的收缩单位: 肌原纤维(myofibrils)","kp":"ch07_s7_27"},{"id":"ch07_ajudge_9","modI":10,"q":"原生动物中的变形虫，高等动物中的巨噬细","a":"对","e":"本页要点：原生动物中的变形虫，高等动物中的巨噬细","kp":"ch07_s10_45"},{"id":"ch07_ajudge_11","modI":11,"q":"细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","a":"对","e":"本页要点：细胞分裂中微丝和肌球蛋白 II 形成收缩环，相","kp":"ch07_s11_56"},{"id":"ch07_ajudge_2","modI":5,"q":"Cytoplasmic streaming in cylindrical giant algae.","a":"对","e":"本页要点：Cytoplasmic streaming in cylindrical giant algae.","kp":"ch07_s5_23"}],"fill":[{"id":"ch07_fill_1","modI":1,"q":"微丝是由 G-actin 单体形成的多聚体，肌动蛋白单体具有极性，装配时呈头尾相接，故微 丝具有______。正极与负极都能生长，生长快的一端为______，慢的一端为______。","a":"极性；正极；负极","kp":"ch07_s1_4"},{"id":"ch07_fill_2","modI":1,"q":"同微丝相同，微管的装配也具有______。","a":"极性","kp":"ch07_s1_2"},{"id":"ch07_fill_3","modI":1,"q":"微管正极端的蛋白是______，微丝正极端的特点是______。","a":"β-微管蛋白；具有结合 ATP 的位点","kp":"ch07_s1_4"},{"id":"ch07_fill_4","modI":9,"q":"肌球蛋白Ⅱ在细胞中的功能有两个方面：参与_________和_________。","a":"胞质分裂；肌收缩","kp":"ch07_s9_42"},{"id":"ch07_fill_5","modI":8,"q":"微丝是指真核细胞中由________组成，直径为________的骨架纤维。","a":"肌动蛋白；7 nm","kp":"ch07_s8_37"}],"term":[{"id":"ch07_term_1","modI":2,"term":"肌球蛋白（myosin）。","def":"肌球蛋白（myosin）是微丝的化学组成之一，有 1 杆部和 2 个头部，每个头部 2 条轻链， 具有 ATP 酶活性。头部具有肌动蛋白结合点，可与肌动蛋白结合，在粗肌丝中作为一种收 缩蛋白参与肌肉收缩活动。","kps":"","kp":"ch07_s2_18"},{"id":"ch07_term_2","modI":3,"term":"细胞松弛素（cytochalasin）。","def":"细胞松弛素是真菌的一类代谢产物，与微丝结合后可以将微丝切断，并结合在微丝末端 阻抑肌动蛋白在该部位的聚合，是微丝聚合的特异性抑制剂，常用的有细胞松弛素 B 和细 胞松弛素 D。","kps":"","kp":"ch07_s3_21"},{"id":"ch07_term_3","modI":3,"term":"鬼笔环肽（phalloidin）。","def":"鬼笔环肽是由鬼笔鹅膏真菌（Amanka phallodines）产生的一种环肽，对微丝表面具有 很强的亲和力，但不与肌动蛋白单体结合，对微丝的解聚有抑制作用，使微丝保持稳定状态。","kps":"","kp":"ch07_s3_21"},{"id":"ch07_term_4","modI":9,"term":"应力纤维（stress fiber）。","def":"真核细胞胞质内由微丝平行排列构成的微丝束称为应力纤维。它参与黏合斑的形成和细 胞的移动。在细胞的形态发生、细胞分化和组织形成中，应力纤维具有重要的作用。","kps":"","kp":"ch07_s9_42"}],"short":[{"id":"ch07_short_1","modI":10,"q":"简述微丝的结构特点。","a":"肌动蛋白（actin）是微丝的结构成分，以单体和多聚体两种形式存在。单体肌动蛋白又 称球状肌动蛋白（G-actin），G-actin 的多聚体形成肌动蛋白丝，称为纤维状肌动蛋白（F-actin）， 在电镜下微丝是一条直径为 7nm 的扭链，呈双股螺旋状。肌动蛋白单体具有极性，装配时 呈头尾相接，故微丝也具有极性，即正极与负极之别。","kp":"ch07_s10_49"},{"id":"ch07_short_2","modI":2,"q":"影响微丝装配的因素有哪些？","a":"影响微丝装配的因素包括： （1）微丝的装配受肌动蛋白临界浓度的影响。在正常的体外条件下，单体的临界浓度（critical concentration，Cc）Cc 是 0.1mol／L。高于该值，G-肌动蛋白倾向于聚合，低于该值，F\"肌 动蛋白将会解聚。所以 Cc 可用它来测定溶液中 G-肌动蛋白聚合的能力。 （2）在肌动蛋白纤维的装配过程还受一些离子浓度的影响。例如，向 G 肌动蛋白溶液中添 加 Mg2 、K 、Na ，可诱导 p 肌动蛋白聚合成 F-肌动蛋白。该过程是可逆的，当这些离子 ＋     ＋   ＋   的浓度较低时，F-肌动蛋白趋于去聚合，而在 Mg2 和高浓度 K 或 Na 的溶液诱导下，G- ＋  ＋  ＋   肌动蛋白则装配成纤维状肌动蛋白。","kp":"ch07_s2_10"},{"id":"ch07_short_3","modI":2,"q":"简述微丝的形态和化学组成。","a":"微丝是一种普遍存在于真核细胞中的实心纤维，其直径约为 6nm，常成群或成束存在于 胞质内。在高度持化的细胞，如肌细胞能形成稳定的结构，但更常见的是在非肌细胞内形成 不稳定的束或复杂的网。微丝主要由 3 类蛋白质组成，一类是肌动蛋白，是微丝的基础蛋白； 另一类是肌球蛋 A，肌球蛋白和肌动蛋白共同作为收缩蛋白在收缩中起主要作用，还有一类 是肌动蛋白一结合蛋白，已经发现这类结合蛋白有 40 多种，它们在微丝中具有不同的功能， 与肌动蛋白纤维的结合、聚合及稳定等作用有关。","kp":"ch07_s2_13"},{"id":"ch07_short_4","modI":9,"q":"何谓细胞骨架？微管、微丝在细胞骨架中的主要作用是什么？","a":"细胞骨架是细胞内以蛋白质纤维为主要成分的网络结构，由微管、微丝、中间纤维组成。 微管功能大致分为四个方面：支架作用，维持细胞形态、定位细胞器；作为胞内物质运输的 轨道；作为纤毛、鞭毛的运动元件；参与细胞分裂。微丝的功能包括：肌细胞中参与肌原纤 维收缩；在非肌细胞中参与胞质分裂、胞质环流、吞噬作用、细胞变形运动、膜泡运输、细 胞黏着与连接等。中间纤维为细胞提供机械强度支持；参与细胞连接（桥粒与半桥粒）；维 持核膜稳定；结蛋白（desmin）及相关蛋白对肌节的稳定作用。","kp":"ch07_s9_42"}],"calc":[],"appcards":[{"front":"简述微丝的结构特点。","back":"肌动蛋白（actin）是微丝的结构成分，以单体和多聚体两种形式存在。单体肌动蛋白又 称球状肌动蛋白（G-actin），G-actin 的多聚体形成肌动蛋白丝，称为纤维状肌动蛋白（F-actin）， 在电镜下微丝是一条直径为 7nm 的扭链，呈双股螺旋状。肌动蛋白单体具有极性，装配时 呈头尾相接，故微丝也具有极性，即正极与负极之别。","mod":10,"modName":"第二节 微丝 · 2.4.4 细胞爬行运动(cell crawling, cell","points":""},{"front":"影响微丝装配的因素有哪些？","back":"影响微丝装配的因素包括： （1）微丝的装配受肌动蛋白临界浓度的影响。在正常的体外条件下，单体的临界浓度（critical concentration，Cc）Cc 是 0.1mol／L。高于该值，G-肌动蛋白倾向于聚合，低于该值，F\"肌 动蛋白将会解聚。所以 Cc 可用它来测定溶液中 G-肌动蛋白聚合的能力。 （2）在肌动蛋白纤维的装配过程还受一些离子浓度的影响。例如，向 G 肌动蛋白溶液中添 加 Mg2 、K 、Na ，可诱导 p 肌动蛋白聚合成 F-肌动蛋白。该过程是可逆的，当这些离子 ＋     ＋   ＋   的浓度较低时，F-肌动蛋白趋于去聚合，而在 Mg2 和高浓度 K 或 Na 的溶液诱导下，G- ＋  ＋  ＋   肌动蛋白则装配成纤维状肌动蛋白。","mod":2,"modName":"第二节 微丝 · 2.2 微丝结合蛋白","points":""},{"front":"简述微丝的形态和化学组成。","back":"微丝是一种普遍存在于真核细胞中的实心纤维，其直径约为 6nm，常成群或成束存在于 胞质内。在高度持化的细胞，如肌细胞能形成稳定的结构，但更常见的是在非肌细胞内形成 不稳定的束或复杂的网。微丝主要由 3 类蛋白质组成，一类是肌动蛋白，是微丝的基础蛋白； 另一类是肌球蛋 A，肌球蛋白和肌动蛋白共同作为收缩蛋白在收缩中起主要作用，还有一类 是肌动蛋白一结合蛋白，已经发现这类结合蛋白有 40 多种，它们在微丝中具有不同的功能， 与肌动蛋白纤维的结合、聚合及稳定等作用有关。","mod":2,"modName":"第二节 微丝 · 2.2 微丝结合蛋白","points":""},{"front":"何谓细胞骨架？微管、微丝在细胞骨架中的主要作用是什么？","back":"细胞骨架是细胞内以蛋白质纤维为主要成分的网络结构，由微管、微丝、中间纤维组成。 微管功能大致分为四个方面：支架作用，维持细胞形态、定位细胞器；作为胞内物质运输的 轨道；作为纤毛、鞭毛的运动元件；参与细胞分裂。微丝的功能包括：肌细胞中参与肌原纤 维收缩；在非肌细胞中参与胞质分裂、胞质环流、吞噬作用、细胞变形运动、膜泡运输、细 胞黏着与连接等。中间纤维为细胞提供机械强度支持；参与细胞连接（桥粒与半桥粒）；维 持核膜稳定；结蛋白（desmin）及相关蛋白对肌节的稳定作用。","mod":9,"modName":"第二节 微丝 · 2.4.3 应力纤维(Stress fi","points":""}]};